"Eine <0>hebbare Lücke</0> entsteht, wenn Zähler und Nenner an derselben Stelle {1} werden und sich der Faktor kürzen lässt.": "<0>Megszüntethető szakadás</0> akkor keletkezik, ha a számláló és a nevező ugyanazon a helyen lesz {1}, és a tényező egyszerűsíthető.",
