"Gesucht: x₁, x₂ mit x₁ + x₂ = {0} und x₁ · x₂ = {1}": "Keresett: x₁, x₂, ahol x₁ + x₂ = {0} és x₁ · x₂ = {1}",
"Gibt an, wie oft der Linearfaktor (x − x₀) im Produkt vorkommt. Einfache NS (n={0}): Graph kreuzt die x-Achse. Doppelte NS (n={1}): Graph berührt die x-Achse (Wendepunkt bei der NS möglich).": "Megadja, hányszor fordul elő az (x − x₀) lineáris tényező a szorzatban. Egyszeres zérushely (n={0}): a grafikon metszi az x-tengelyt. Kétszeres zérushely (n={1}): a grafikon érinti az x-tengelyt (a zérushelyen inflexiós pont lehetséges).",
"Gibt den absoluten (nicht-negativen) Wert von x zurück: |x| = x für x ≥ {0}, |x| = −x für x {1} {2}. Graph: V-förmig mit Knick bei x = {3}. Nicht differenzierbar bei x = {4}.": "Az x abszolút (nemnegatív) értékét adja vissza: |x| = x, ha x ≥ {0}, |x| = −x, ha x {1} {2}. Grafikon: V alakú, törésponttal: x = {3}. Nem differenciálható itt: x = {4}.",
