"<0>Steigung</0>: Zwei Geraden stehen genau dann senkrecht aufeinander, wenn {1} gilt. Mit {2} folgt:": "<0>Meredekség</0>: két egyenes pontosan akkor merőleges egymásra, ha {1}. {2} esetén:",
"Senkrechte: {0}": "Merőleges: {0}",
"{0}: Mittelsenkrechte der Strecke {1} mit {2} und {3}": "{0}: az {1} szakasz felezőmerőlegese, ahol {2} és {3}",
"<0>Mittelpunkt</0> {1} der Strecke {2}:": "A(z) {2} szakasz <0>felezőpontja</0> ({1}):",
"<0>Steigung</0>: Die Strecke {1} hat die Steigung": "<0>Meredekség</0>: az {1} szakasz meredeksége",
"Senkrechte Geraden erfüllen {0}, also:": "A merőleges egyenesekre {0} teljesül, tehát:",
"Mittelsenkrechte: {0}": "Felezőmerőleges: {0}",
"Die Strecke {0} ist senkrecht ({1}). Die Mittelsenkrechte steht darauf senkrecht, ist also <2>waagrecht</2> und geht durch {3}:": "A(z) {0} szakasz függőleges ({1}). A felezőmerőleges merőleges rá, tehát <2>vízszintes</2>, és átmegy a(z) {3} ponton:",
"Die Koordinaten sind auf {0} Nachkommastellen gerundet.": "A koordináták {0} tizedesjegyre vannak kerekítve.",
"Noch keine Senkrechte oder Mittelsenkrechte erstellt.": "Még nincs létrehozva merőleges vagy felezőmerőleges.",
