"Löschen: Punkt, Graph oder Objekt anklicken, um es zu entfernen": "Törlés: kattints egy pontra, grafikonra vagy objektumra az eltávolításhoz",
"Punkt setzen: in den Plot klicken (rastet am Gitter ein). Punkte lassen sich danach ziehen.": "Pont elhelyezése: kattints a grafikonra (a rácshoz igazodik). A pontok utána húzhatók.",
"Punkt setzen: in den Plot klicken. Punkte lassen sich danach ziehen.": "Pont elhelyezése: kattints a grafikonra. A pontok utána húzhatók.",
"Punkt auf Graph: auf eine Kurve klicken. Der Punkt bleibt auf dem Graphen und lässt sich daran entlang ziehen.": "Pont a grafikonon: kattints egy görbére. A pont a grafikonon marad, és mentén húzható.",
"Gerade durch 2 Punkte: ersten Punkt wählen (bestehenden anklicken oder neu setzen)": "Egyenes két ponton át: válaszd ki az első pontot (kattints egy meglévőre vagy helyezz el újat)",
"Gerade durch 2 Punkte: zweiten Punkt wählen": "Egyenes két ponton át: válaszd ki a második pontot",
"Steigungsdreieck: ersten Punkt auf einer Geraden anklicken": "Meredekségi háromszög: kattints az első pontra egy egyenesen",
"Steigungsdreieck: zweiten Punkt auf derselben Geraden anklicken": "Meredekségi háromszög: kattints a második pontra ugyanazon az egyenesen",
"Parabel durch 3 Punkte: ersten Punkt wählen": "Parabola három ponton át: válaszd ki az első pontot",
"Parabel durch 3 Punkte: zweiten Punkt wählen": "Parabola három ponton át: válaszd ki a második pontot",
"Parabel durch 3 Punkte: dritten Punkt wählen": "Parabola három ponton át: válaszd ki a harmadik pontot",
"Parabel aus Scheitelpunkt und Punkt: Scheitelpunkt S wählen": "Parabola csúcsból és pontból: válaszd ki az S csúcsot",
"Parabel aus Scheitelpunkt und Punkt: Punkt P auf der Parabel wählen": "Parabola csúcsból és pontból: válassz egy P pontot a parabolán",
"Parabel aus Nullstellen und Punkt: erste Nullstelle wählen (liegt auf der x-Achse)": "Parabola zérushelyekből és pontból: válaszd ki az első zérushelyet (az x-tengelyen van)",
"Parabel aus Nullstellen und Punkt: zweite Nullstelle wählen (liegt auf der x-Achse)": "Parabola zérushelyekből és pontból: válaszd ki a második zérushelyet (az x-tengelyen van)",
"Parabel aus Nullstellen und Punkt: Punkt P auf der Parabel wählen": "Parabola zérushelyekből és pontból: válassz egy P pontot a parabolán",
"Senkrechte: Punkt wählen, durch den sie gehen soll": "Merőleges: válaszd ki a pontot, amelyen át haladjon",
"Senkrechte: Gerade anklicken, zu der sie senkrecht stehen soll": "Merőleges: kattints arra az egyenesre, amelyre merőleges legyen",
"Mittelsenkrechte: ersten Punkt der Strecke wählen": "Felezőmerőleges: válaszd ki a szakasz első végpontját",
"Mittelsenkrechte: zweiten Punkt der Strecke wählen": "Felezőmerőleges: válaszd ki a szakasz második végpontját",
"Differenzenquotient: Die Punkte A und B auf dem Graphen ziehen. Rücken sie zusammen, wird die Sekante zur Tangente.": "Különbségi hányados: húzd az A és B pontot a grafikon mentén. Ha közel kerülnek, a szelő érintővé válik.",
"Ober-/Untersummen: Die Grenzen a und b im Plot ziehen. Die Anzahl der Rechtecke stellst du im Panel ein.": "Alsó/felső összegek: húzd az a és b határokat a grafikonon. A téglalapok számát a panelen állíthatod be.",
"Fläche: Die Grenzen a und b im Plot ziehen (sie rasten an Schnittpunkten ein).": "Terület: húzd az a és b határokat a grafikonon (a metszéspontokhoz igazodnak).",
"Zielfunktion: Den Griff im Plot verschieben. Er rastet an den Ecken des Planungspolygons ein.": "Célfüggvény: told el a fogantyút a grafikonon. A feltételek sokszögének csúcsaihoz igazodik.",
