"Beide Glieder enthalten {0}x. Man klammert es aus: {1}x({2}x + {3}).": "Mindkét tag tartalmazza ezt: {0}x. Kiemeljük: {1}x({2}x + {3}).",
"Ein x², fünf x und sechs {0} werden zu einem Rechteck gelegt. Gesucht: zwei Zahlen mit Produkt {1} und Summe {2}.": "Egy x², öt x és hat {0} egy téglalappá rakódik. Keresünk két számot, amelyek szorzata {1}, összege {2}.",
"Produkt −{0} und Summe −{1}: die Zahlen sind −{2} und {3}.": "Szorzat −{0}, összeg −{1}: a számok −{2} és {3}.",
"Aus x² − {0} wird (x + {1})(x − {2}): Der Streifen wird umgelegt.": "x² − {0} átalakítva: (x + {1})(x − {2}) – a csíkot átfordítjuk.",
"Quadrat, doppeltes Produkt, Quadrat: es ist ({0}x − {1}y)².": "Négyzet, kétszeres szorzat, négyzet: ez ({0}x − {1}y)².",
"Zuerst den gemeinsamen Faktor {0}, dann die dritte binomische Formel: {1}(x + {2})(x − {3}).": "Először a közös tényező ({0}), majd a harmadik nevezetes azonosság: {1}(x + {2})(x − {3}).",
