"Fehlt dem Quadrat nur noch ein kleines Eckquadrat, dann ergänzt man genau dieses – und hat ein vollständiges Quadrat.": "Ha a négyzetből csak egy kis saroknégyzet hiányzik, akkor pontosan azt egészítjük ki – és kész a teljes négyzet.",
