"√{0} = {1}√{2}; dann {3}√{4} − √{5} = {6}√{7}.": "√{0} = {1}√{2}; majd {3}√{4} − √{5} = {6}√{7}.",
"Zwei Drittel und ein Drittel ergeben einen ganzen Baustein: ∛(x²) · ∛x = x.": "Kétharmad és egyharmad egy egész építőelemet ad: ∛(x²) · ∛x = x.",
