"Urnenmodelle (Ziehen von Kugeln)": "Urnamodellek (golyóhúzás)",
"Aus einer Urne mit n nummerierten Kugeln werden k Kugeln gezogen. Zwei Fragen legen das Modell fest: Wird zurückgelegt? Zählt die Reihenfolge?": "Egy n számozott golyót tartalmazó urnából k golyót húzunk ki. Két kérdés határozza meg a modellt: visszatesszük a golyót? Számít a sorrend?",
"Beobachte: Die vier Kombinationen ergeben vier Zählformeln. Mit «Neue Ziehung» siehst du ein Beispiel; die Rechnung zeigt die Anzahl der Möglichkeiten und die Wahrscheinlichkeit.": "Figyeld meg: a négy kombináció négy számolási képletet ad. Az „Új húzás” gombbal példát látsz; a számítás megmutatja a lehetőségek számát és a valószínűséget.",
"Eine Variante erklären": "Egy változat magyarázata",
"Alle vier vergleichen": "Mind a négy összehasonlítása",
"Kugeln in der Urne n": "Golyók az urnában n",
"Gezogene Kugeln k": "Kihúzott golyók k",
"{0} <1>Mit Zurücklegen</1>": "{0} <1>Visszatevéssel</1>",
"{0} <1>Mit Reihenfolge</1>": "{0} <1>Sorrenddel</1>",
"Neue Ziehung": "Új húzás",
"Gezogene Kugeln bleiben draussen. Beim ersten Zug hat man n Möglichkeiten, beim zweiten n − {0}, … beim k-ten n − k + {1}. Die Reihenfolge zählt. Multiplikationsprinzip: n · (n − {2}) · … · (n − k + {3}) = n!/(n − k)!.": "A kihúzott golyók kint maradnak. Az első húzásnál n lehetőség van, a másodiknál n − {0}, … a k-adiknál n − k + {1}. A sorrend számít. Szorzási szabály: n · (n − {2}) · … · (n − k + {3}) = n!/(n − k)!.",
"Alle {0} Möglichkeiten sind gleich wahrscheinlich.": "Mind a {0} lehetőség egyformán valószínű.",
"Urne mit {0} Kugeln, {1} werden gezogen": "Urna {0} golyóval, {1}-t húzunk ki",
"Urne mit {0} Kugeln, eine wird gezogen": "Urna {0} golyóval, egyet húzunk ki",
"zurücklegen": "visszatenni",
"Folge der gezogenen Kugeln (Reihenfolge zählt)": "A kihúzott golyók sorozata (a sorrend számít)",
"Menge der gezogenen Kugeln (Reihenfolge egal)": "A kihúzott golyók halmaza (a sorrend nem számít)",
"Variation ohne Wiederholung": "Ismétlés nélküli variáció",
"Variation mit Wiederholung": "Ismétléses variáció",
"Kombination ohne Wiederholung": "Ismétlés nélküli kombináció",
"Kombination mit Wiederholung": "Ismétléses kombináció",
"ohne Zurücklegen, mit Reihenfolge": "visszatevés nélkül, sorrenddel",
"mit Zurücklegen, mit Reihenfolge": "visszatevéssel, sorrenddel",
"ohne Zurücklegen, ohne Reihenfolge": "visszatevés nélkül, sorrend nélkül",
"mit Zurücklegen, ohne Reihenfolge": "visszatevéssel, sorrend nélkül",
"Anzahl Möglichkeiten:": "A lehetőségek száma:",
"Wahrscheinlichkeit für das gezogene Ergebnis:": "A kihúzott eredmény valószínűsége:",
"Jede gezogene Kugel wird zurückgelegt, darum hat man bei jedem der k Züge wieder n Möglichkeiten. Die Reihenfolge zählt: ({0}, {1}) und ({2}, {3}) sind verschieden. Multiplikationsprinzip: n · n · … · n mit k Faktoren.": "Minden kihúzott golyót visszatesznek, ezért a k húzás mindegyikénél újra n lehetőség van. A sorrend számít: ({0}, {1}) és ({2}, {3}) különböző. Szorzási szabály: n · n · … · n, k tényezővel.",
"Es zählt nur, welche Kugeln gezogen wurden (wie bei einem Griff in die Urne). Jede Auswahl von k Kugeln lässt sich auf k! Arten anordnen. Darum teilt man die Zahl der Variationen n!/(n − k)! durch k!. Das ist der Binomialkoeffizient «n über k».": "Csak az számít, hogy mely golyókat húzták ki (mint amikor egy marékkal veszünk az urnából). A k golyó minden kiválasztása k! féleképpen rendezhető. Ezért a variációk n!/(n − k)! számát osztjuk k!-sal. Ez az „n alatt a k” binomiális együttható.",
"Die Kugeln werden zurückgelegt, aber nur die gezogene Menge zählt: Kugeln dürfen mehrfach vorkommen, die Reihenfolge nicht. Zählen mit Sternen und Strichen: k Kugeln («Sterne») und n − {0} Trennstriche zwischen den n Nummern ergeben n + k − {1} Plätze, auf denen man k für die Sterne wählt.": "A golyókat visszateszik, de csak a kihúzott halmaz számít: a golyók többször is előfordulhatnak, a sorrend nem számít. Számolás csillagokkal és vonalakkal: k golyó („csillagok”) és az n szám közötti n − {0} elválasztó vonal n + k − {1} helyet ad, amelyek közül k-t választunk a csillagoknak.",
"Die Möglichkeiten sind nicht gleich wahrscheinlich: Mengen mit verschiedenen Kugeln kommen häufiger vor.": "A lehetőségek nem egyformán valószínűek: a különböző golyókból álló halmazok gyakrabban fordulnak elő.",
"k = n: Alle Kugeln werden gezogen (Permutation).": "k = n: az összes golyót kihúzzuk (permutáció).",
"Ohne Zurücklegen: Jede Auswahl lässt sich auf k! Arten anordnen. Variationen = k! · Kombinationen:": "Visszatevés nélkül: minden kiválasztás k! féleképpen rendezhető. Variációk = k! · kombinációk:",
"Mit Zurücklegen gibt es meistens mehr Möglichkeiten als ohne.": "Visszatevéssel általában több lehetőség van, mint nélküle.",
"Die vier Urnenmodelle im Vergleich: {0} Kugeln, {1} werden gezogen": "A négy urnamodell összehasonlítása: {0} golyó, {1}-t húzunk ki",
