"Bei dieser Funktion lässt sich der Differenzenquotient nicht zu einem Term vereinfachen, der sich durch {0} kürzen lässt. Die Ableitungsfunktion findest du mit den Ableitungsregeln.": "Ennél a függvénynél a különbségi hányados nem egyszerűsíthető olyan kifejezéssé, amelyet {0}-val egyszerűsíthetnénk. A derivált függvényt a deriválási szabályokkal találod meg.",
