"<0>Schritt {1}:</0> Das Intervall wird in {2} gleich breite Streifen geteilt.": "<0>{1}. lépés:</0> Az intervallumot {2} egyenlő széles sávra osztjuk.",
"<0>Schritt {1}:</0> Auf {2} wächst {3}. Darum ist der rechte Randpunkt eines Streifens der höchste.": "<0>{1}. lépés:</0> {2}-on {3} növekvő. Ezért a sáv jobb végpontja a legmagasabb.",
"<0>Schritt {1}:</0> {2} einsetzen, ausmultiplizieren und die Summenformeln verwenden:": "<0>{1}. lépés:</0> {2} behelyettesítése, beszorzás és az összegképletek használata:",
"<0>Schritt {1}:</0> Grenzwert für {2}: Alle Summanden mit {3} gehen gegen {4}.": "<0>{1}. lépés:</0> Határérték {2} esetén: minden {3}-t tartalmazó tag {4}-hoz tart.",
