"<0>Differentialrechnung</0><1>Differenzenquotient, Sekante und Tangente, Graphisches Ableiten, Ableitungsregeln, Kurvendiskussion</1>": "<0>Differenciálszámítás</0><1>Különbségi hányados, szelő és érintő, grafikus deriválás, deriválási szabályok, függvényvizsgálat</1>",
"<0>Integralrechnung</0><1>Ober- und Untersummen, Integralfunktion und Hauptsatz, Stammfunktion mit Regeln, Flächen zwischen Kurven, Rotationskörper</1>": "<0>Integrálszámítás</0><1>Alsó és felső összegek, integrálfüggvény és alaptétel, primitív függvény szabályokkal, görbék közötti területek, forgástestek</1>",
"<0>Algebra</0><1>Binomische Formeln, Ausmultiplizieren, Faktorisieren, quadratische Ergänzung, Potenzen, Wurzeln, Logarithmen, Bruchterme, Gleichungen und Gleichungssysteme als Bild</1>": "<0>Algebra</0><1>Nevezetes azonosságok, beszorzás, szorzattá alakítás, teljes négyzetté alakítás, hatványok, gyökök, logaritmusok, algebrai törtek, egyenletek és egyenletrendszerek képként</1>",
"<0>Wahrscheinlichkeit & Statistik</0><1>Zufallsexperimente zum Mitverfolgen: Würfel, Galtonbrett, π, Ziegenproblem, Grenzwertsatz, Konfidenzintervalle</1>": "<0>Valószínűség és statisztika</0><1>Követhető véletlen kísérletek: kocka, Galton-deszka, π, Monty Hall-probléma, centrális határeloszlás-tétel, konfidenciaintervallumok</1>",
"<0>Finanzmathematik</0><1>Zeitstrahl und Konten, Summenzeichen, Sparplan, Kredit mit Tilgungsplan, Zeitwert, Marchzins, konformer Zins</1>": "<0>Pénzügyi matematika</0><1>Idővonal és számlák, szummajel, megtakarítási terv, hitel törlesztési tervvel, jelenérték, napi kamat, ekvivalens kamatláb</1>",
"Das Intervall wird in {0} gleich breite Streifen der Breite {1} geteilt. Die <2>Untersumme</2> nimmt in jedem Streifen den kleinsten, die <3>Obersumme</3> den grössten Funktionswert als Höhe des Rechtecks.": "Az intervallumot {0} egyenlő, {1} széles sávra osztjuk. Az <2>alsó összeg</2> minden sávban a legkisebb függvényértéket veszi a téglalap magasságának, a <3>felső összeg</3> a legnagyobbat.",
"Für {0} streben beide Summen gegen {1}.": "{0} esetén mindkét összeg {1}-hez tart.",
"<0>Schritt {1}:</0> {2} einsetzen, ausmultiplizieren.": "<0>{1}. lépés:</0> {2} behelyettesítése és beszorzás.",
"Oben der Graph von f mit der gefärbten Fläche von a bis x, unten die Integralfunktion Fa(x) = ∫ f. Ziehe den Punkt x: Der untere Punkt zeigt, wie viel Fläche bis dahin gesammelt wurde.": "Fent: f grafikonja az a-tól x-ig színezett területtel; lent: az Fa(x) = ∫ f integrálfüggvény. Húzd az x pontot: az alsó pont mutatja, mennyi terület gyűlt össze addig.",
"Die Steigung von Fa an der Stelle x ist {0}: Wo f positiv ist, steigt Fa (grün), wo f negativ ist, fällt Fa (orange). Das ist der Hauptsatz.": "Fa meredeksége az x helyen {0}: ahol f pozitív, Fa nő (zöld), ahol f negatív, Fa csökken (narancs). Ez az alaptétel.",
"Untere Grenze und Stelle": "Alsó határ és hely",
