"Die Fläche zwischen f und der x-Achse (oder zwischen f und g) wird an den Schnittstellen in Stücke geteilt. Stücke über der Achse (bzw. über g) sind grün, darunter orange.": "Az f és az x-tengely (vagy f és g) közötti területet a metszéspontoknál darabokra osztjuk. A tengely (ill. g) feletti darabok zöldek, az alattiak narancssárgák.",
"Flächen zählen immer positiv: Beim Integral heben sich grüne und orange Stücke teilweise auf, bei der Fläche nicht.": "A területek mindig pozitívak: az integrálban a zöld és a narancssárga darabok részben kioltják egymást, a területben nem.",
