"Dreht man den Graphen von f um die x-Achse, entsteht ein Körper aus lauter dünnen Kreisscheiben. Jede Scheibe hat das Volumen π · {0}² · Δx.": "Ha f grafikonját az x-tengely körül forgatjuk, sok vékony korongból álló test keletkezik. Minden korong térfogata π · {0}² · Δx.",
"Erhöhe die Zahl der Scheiben: Die Summe der Scheibenvolumen nähert sich dem Volumen V = π ∫ f².": "Növeld a korongok számát: a korongok térfogatának összege közelít a V = π ∫ f² térfogathoz.",
