"Parabel und Gerade, Parabel aus Punkten": "Parabola és egyenes, parabola pontokból",
"Eine quadratische Funktion {0} = ax² + bx + c hat eine Parabel als Graph. Der Faktor a streckt die Normalparabel (bei a {1} {2} gespiegelt), der Scheitel S ist der höchste oder tiefste Punkt.": "Másodfokú függvény: {0} = ax² + bx + c, grafikonja parabola. Az a tényező nyújtja az y = x² alapparabolát (a {1} {2} esetén tükrözi is), az S csúcs a legmagasabb vagy legalacsonyabb pont.",
"Ziehe den Scheitel S, den roten Punkt (a), den Achsenabschnitt c oder die Nullstellen N. Standard-, Scheitel- und Nullstellenform beschreiben dieselbe Parabel.": "Húzd az S csúcsot, a piros pontot (a), a c tengelymetszetet vagy az N zérushelyeket. Az általános alak, a csúcsalak és a gyöktényezős alak ugyanazt a parabolát írja le.",
