"Der Schnittpunkt zweier Geraden löst beide Gleichungen gleichzeitig. Die Tabelle zeigt, wo die y-Werte von f und g übereinstimmen.": "Két egyenes metszéspontja mindkét egyenletet egyszerre megoldja. A táblázat azt mutatja, hol egyeznek meg f és g y-értékei.",
