"Die Lösungen sind keine einfachen Zahlen: Das Raten mit Vieta führt hier nicht weiter. Mit der Mitternachtsformel:": "A megoldások nem egyszerű számok: a Viète-féle találgatás itt nem visz tovább. Megoldóképlettel:",
"Gerade und Parabel: Gleichsetzen gibt eine quadratische Gleichung, deren Diskriminante die Anzahl der Schnittpunkte bestimmt (Sekante, Tangente, Passante). Umgekehrt legen drei Punkte, oder Scheitel und Punkt, oder zwei Nullstellen und ein Punkt eine Parabel fest.": "Egyenes és parabola: az egyenlővé tétel másodfokú egyenletet ad, amelynek diszkriminánsa meghatározza a metszéspontok számát (szelő, érintő, elkerülő). Fordítva: három pont, vagy a csúcs és egy pont, vagy két zérushely és egy pont meghatároz egy parabolát.",
"Ziehe die Punkte und Griffe. Mit «Gerade berühren lassen» wird die Gerade bei gleicher Steigung zur Tangente.": "Húzd a pontokat és a fogópontokat. Az «Egyenes érintővé tétele» gombbal az egyenes azonos meredekségnél érintővé válik.",
