"{0} Ziehe die Ecken und die Griffe im Bild. Oben links wählst du die Ansicht, rechts steht der Rechenweg.": "{0} Húzd a csúcsokat és a fogópontokat az ábrán. Bal felül választod a nézetet, jobb oldalt áll a levezetés.",
