"<0>Gleiche Winkel gefunden:</0> Die Ecken mit gleichen Winkeln entsprechen sich:": "<0>Egyenlő szögek:</0> az egyenlő szögű csúcsok felelnek meg egymásnak:",
"<0>Merke:</0> Zwei Dreiecke sind ähnlich, wenn sie in allen drei Winkeln übereinstimmen. Wegen der Winkelsumme {1} genügen zwei gleiche Winkel.": "<0>Jegyezd meg:</0> két háromszög hasonló, ha mindhárom szögük megegyezik. A {1} szögösszeg miatt két egyenlő szög is elég.",
