"Zwei Dreiecke (ABC und PQR) sind ähnlich, wenn sie in allen Winkeln übereinstimmen. Dann sind auch alle entsprechenden Seitenverhältnisse gleich. Gleiche Farben zeigen, welche Ecken und Seiten sich entsprechen.": "Két háromszög (ABC és PQR) hasonló, ha minden szögük megegyezik. Ekkor a megfelelő oldalak arányai is mind egyenlők. Az azonos színek mutatják, mely csúcsok és oldalak felelnek meg egymásnak.",
"PQR": "PQR",
"Ziehe die Ecken von {0} und {1}: Stimmen alle Winkel überein, sind die Dreiecke ähnlich, und alle entsprechenden Seitenverhältnisse sind gleich. Gleiche Farben zeigen, was sich entspricht.": "Húzd a {0} és a {1} háromszög csúcsait: ha minden szög megegyezik, a háromszögek hasonlók, és a megfelelő oldalak arányai mind egyenlők. Az azonos színek mutatják, mi minek felel meg.",
"Beim zweiten Strahlensatz gehören zu den Parallelen immer die Abschnitte von {0} aus, nicht die Abschnitte {1} und {2}.": "A párhuzamos szelőszakaszok tételénél a párhuzamosokhoz mindig a {0}-től mért szakaszok tartoznak, nem a {1} és a {2} szakasz.",
"<0>Fehlende Länge berechnen:</0> Gesucht ist {1}, bekannt sind {2}, {3} und {4}. Verhältnisgleichung aufstellen und nach {5} auflösen:": "<0>Hiányzó hossz kiszámítása:</0> keressük a {1} hosszt; ismert {2}, {3} és {4}. Írd fel az aránypárt, és fejezd ki belőle {5}-t:",
"<0>Zweiter Strahlensatz:</0> Die Parallelen stehen im gleichen Verhältnis wie die Abschnitte von {1} aus.": "<0>Párhuzamos szelőszakaszok tétele:</0> a párhuzamos szakaszok aránya megegyezik a {1}-től mért szakaszok arányával.",
"Ebenso die Abschnitte zwischen den Parallelen:": "Ugyanígy a párhuzamosok közötti szakaszok:",
"<0>Erster Strahlensatz:</0> Die Abschnitte von {1} aus stehen auf beiden Strahlen im gleichen Verhältnis.": "<0>Párhuzamos szelők tétele:</0> a {1}-től mért szakaszok aránya a két félegyenesen megegyezik.",
"<0>Ähnliche Dreiecke:</0> Weil {1}, stimmen {2} und {3} in allen Winkeln überein (gemeinsamer Winkel bei {4}, Stufenwinkel an Parallelen).": "<0>Hasonló háromszögek:</0> mivel {1}, a {2} és a {3} háromszög minden szöge megegyezik (közös szög {4}-nél, egyállású szögek a párhuzamosoknál).",
"Zwei Strahlen haben den gemeinsamen Anfangspunkt {0}. {1} und {2} liegen auf dem einen, {3} und {4} auf dem anderen Strahl (V-Figur).": "Két félegyenes közös kezdőpontja {0}. {1} és {2} az egyiken, {3} és {4} a másikon van (V-alakzat).",
