"Werden zwei Strahlen mit Anfangspunkt Z von zwei Parallelen geschnitten, so sind die Dreiecke ZAB und ZCD ähnlich. Daraus folgen die Strahlensätze.": "Ha két Z kezdőpontú félegyenest két párhuzamos egyenes metsz, akkor a ZAB és a ZCD háromszög hasonló. Ebből következnek a párhuzamos szelők tételei.",
"Ziehe {0} und {1}: Zwei Parallelen schneiden die Strahlen aus Z, die Dreiecke ZAB und ZCD sind ähnlich – daraus folgen die Strahlensätze. Mit «D frei» siehst du, dass es ohne Parallelen nicht mehr stimmt.": "Húzd a {0} és a {1} pontot: két párhuzamos metszi a Z-ből induló félegyeneseket, a ZAB és a ZCD háromszög hasonló – ebből következnek a párhuzamos szelők tételei. A „D szabad” beállítással láthatod, hogy párhuzamosok nélkül ez már nem igaz.",
"Vorgehen: gleiche Winkel markieren, ähnliche Dreiecke mit entsprechenden Ecken in derselben Reihenfolge notieren, Verhältnisgleichung aufstellen und lösen.": "Eljárás: jelöld meg az egyenlő szögeket, írd fel a hasonló háromszögeket a megfelelő csúcsok azonos sorrendjével, állítsd fel az aránypárt, és oldd meg.",
