"Die Höhe CD teilt das rechtwinklige Dreieck ABC in zwei Teildreiecke. Alle drei Dreiecke haben die Winkel α, β und {0}° und sind deshalb ähnlich: ΔADC ∼ ΔCDB ∼ ΔACB.": "A CD magasság az ABC derékszögű háromszöget két kisebb háromszögre bontja. Mindhárom háromszög szögei α, β és {0}°, ezért hasonlók: ΔADC ∼ ΔCDB ∼ ΔACB.",
"Ziehe {0} auf dem Thaleskreis oder die Ecken {1} und {2}: Die Höhe CD teilt das rechtwinklige Dreieck in zwei Teildreiecke, alle drei sind ähnlich (Winkel α, β, {3}°). Rechts stehen sie in gleicher Lage nebeneinander.": "Húzd a {0} pontot a Thalész-körön, vagy a {1} és a {2} csúcsot: a CD magasság a derékszögű háromszöget két kisebb háromszögre bontja, és mindhárom hasonló (szögek: α, β, {3}°). Jobb oldalt azonos helyzetben állnak egymás mellett.",
"Winkel und Seitenlängen lassen sich links einblenden; rechts stehen die Seitenverhältnisse als Brüche.": "A szögek és az oldalhosszak bal oldalt kapcsolhatók be; jobb oldalt az oldalarányok törtként állnak.",
"«Abbildung vorführen …» spielt einzelne Abbildungen ab; «⟲ Bild auf das Original legen» stellt den Anfang wieder her.": "A „Transzformáció bemutatása …” egyes transzformációkat játszik le; a „⟲ Kép az eredetire” visszaállítja a kezdőállapotot.",
"«Mehrere nacheinander» verknüpft die Abbildungen in fester Reihenfolge: spiegeln, um O drehen, von Z aus strecken, verschieben.": "A „Több egymás után” rögzített sorrendben fűzi össze a transzformációkat: tükrözés, forgatás O körül, középpontos hasonlóság Z-ből, eltolás.",
"Das Original ABC bleibt fest. Unter «Abbildung» wählst du genau eine Grundabbildung: Verschiebung, Drehung um den Ursprung, Spiegelung an der x- oder y-Achse oder zentrische Streckung von Z aus. Das Bild A′B′C′ zeigt dann nur diese eine Abbildung; du kannst es auch mit der Maus verschieben, drehen bzw. strecken.": "Az eredeti ABC a helyén marad. A „Transzformáció” alatt pontosan egy alaptranszformációt választasz: eltolást, origó körüli forgatást, az x- vagy y-tengelyre való tükrözést vagy Z középpontú hasonlóságot. Az A′B′C′ kép ekkor csak ezt az egy transzformációt mutatja; egérrel el is tolhatod, forgathatod, illetve nyújthatod.",
