"Das Dreieck ABC bleibt fest. Sein Bild A′B′C′ entsteht durch Verschieben, Drehen um den Ursprung O, Spiegeln an der x- oder y-Achse und zentrisches Strecken von Z aus. Die ersten drei Abbildungen erhalten alle Längen (Bild und Original sind kongruent), die Streckung multipliziert jede Länge mit |k|. Die Winkel bleiben immer gleich.": "Az ABC háromszög a helyén marad. Az A′B′C′ képe eltolással, az O origó körüli forgatással, az x- vagy y-tengelyre való tükrözéssel és Z középpontú hasonlósággal jön létre. Az első három transzformáció minden hosszt megtart (a kép és az eredeti egybevágó); a középpontos hasonlóság minden hosszt |k|-szorosára változtat. A szögek mindig ugyanakkorák maradnak.",
