"Eine Ebene im Raum hat die Koordinatenform a·x + b·y + c·z = d. Der Normalenvektor (a | b | c) steht senkrecht auf ihr. Achsenabschnitte: zwei Koordinaten null setzen. Buchstaben in der Gleichung werden zu Schiebern.": "Egy térbeli sík általános egyenlete a·x + b·y + c·z = d. Az (a | b | c) normálvektor merőleges rá. Tengelymetszetek: két koordinátát nullának veszünk. Az egyenletben szereplő betűkből csúszkák lesznek.",
