"Lagemasse: Mittelwert (Summe durch Anzahl), Median (Wert in der Mitte der geordneten Liste), Modus (häufigster Wert). Streumasse: Spannweite, Quartilsabstand Q₃ − Q₁ und Standardabweichung. Diagramme: Punkt-, Säulen-, Kreisdiagramm, Histogramm (Klassen) und Boxplot.": "Helyzetmutatók: átlag (összeg osztva a darabszámmal), medián (a rendezett lista középső értéke), módusz (a leggyakoribb érték). Szóródási mutatók: terjedelem, interkvartilis terjedelem Q₃ − Q₁ és szórás. Diagramok: pont-, oszlop- és kördiagram, hisztogram (osztályok) és dobozdiagram.",
"{0}Statistik und Stochastik rechnen{1}": "{0}Statisztika és valószínűség: számítások{1}",
