"]a; b[ (nach aussen gedrehte Klammer)": "]a; b[ (kifelé fordított szögletes zárójel)",
"(a, b) (runde Klammer)": "(a, b) (kerek zárójel)",
"Schreibweise": "Írásmód",
"Ein Intervall ist die Menge aller reellen Zahlen zwischen zwei Randpunkten. Gehört ein Randpunkt dazu, steht eine eckige Klammer nach innen und ein gefüllter Punkt; sonst eine nach aussen gedrehte (oder runde) Klammer und ein leerer Punkt. Bei ±∞ ist das Intervall offen.": "Az intervallum a két végpont közötti összes valós szám halmaza. Ha egy végpont hozzátartozik, befelé forduló szögletes zárójelet és teli pontot írunk; különben kifelé fordított (vagy kerek) zárójelet és üres pontot. ±∞-nél az intervallum nyitott.",
"{0}Exponential- und Logarithmusfunktionen{1}": "{0}Exponenciális és logaritmusfüggvények{1}",
"Exponentialfunktionen {0} = a·bˣ + d: Der Anfangswert a wird bei jedem Schritt um {1} mit demselben Faktor b multipliziert. Für b {2} {3} wächst der Graph (Wachstum um (b−{4})·{5} %), für {6} {7} b {8} {9} fällt er (Zerfall). Die Gerade y = d ist Asymptote.": "Exponenciális függvények: {0} = a·bˣ + d. Az a kezdőérték minden {1} egységnyi lépésnél ugyanazzal a b tényezővel szorzódik. Ha b {2} {3}, a grafikon nő (a növekedés (b−{4})·{5} %), ha {6} {7} b {8} {9}, csökken (bomlás). Az y = d egyenes aszimptota.",
"a: Anfangswert, b: Faktor (Basis), d: Asymptote": "a: kezdőérték, b: szorzótényező (alap), d: aszimptota",
"Basis e (≈ {0})": "e alap (≈ {0})",
"Faktor-Schritte ·b zeigen": "A ·b szorzólépések megjelenítése",
"Vergleich mit linearem Wachstum": "Összehasonlítás a lineáris növekedéssel",
"Asymptote y = d zeigen": "Az y = d aszimptota megjelenítése",
"Am Einheitskreis (Radius {0}) wird der Winkel φ gegen den Uhrzeigersinn abgetragen. Der Punkt P hat die Koordinaten (cos φ | sin φ): Kosinus = waagrechter Abstand, Sinus = Höhe. Im Bogenmass misst man den Winkel als Bogenlänge: {1}° entsprechen {2}π.": "Az egységkörön (sugár: {0}) a φ szöget az óramutató járásával ellentétesen mérjük fel. A P pont koordinátái (cos φ | sin φ): koszinusz = vízszintes távolság, szinusz = magasság. Ívmértékben a szöget az ív hosszával mérjük: {1}° megfelel {2}π-nek.",
