"Ziehe die {0} oder tippe links eine Liste ein: {1} und {2} wandern mit, der {3} zeigt die {4}. Wie stark zieht ein Ausreisser den Mittelwert, wie wenig den Median?": "Húzd az {0}, vagy írj be bal oldalt egy listát: az {1} és a {2} együtt mozog velük, a {3} pedig megmutatja a {4}. Mennyire húzza el egy kiugró érték az átlagot, és milyen kevéssé a mediánt?",
"{0} Ziehe die Punkte im Bild oder ändere links die Zahlen; oben links wählst du die Ansicht, rechts steht der Rechenweg.": "{0} Húzd a pontokat az ábrán, vagy változtasd meg a számokat bal oldalt; bal felül választod a nézetet, jobb oldalt áll a levezetés.",
"<0>Quartile:</0> Der Median teilt die Liste in eine untere und eine obere Hälfte (der Median selbst gehört zu keiner Hälfte). {1} ist der Median der unteren, {2} der Median der oberen Hälfte.": "<0>Kvartilisek:</0> a medián a listát alsó és felső félre osztja (maga a medián egyik félhez sem tartozik). {1} az alsó fél mediánja, {2} a felső fél mediánja.",
