"Die Poissonverteilung beschreibt, <0>wie oft ein Ereignis</0> in einem festen Zeitraum (oder auf einer Seite, einer Strecke, einer Fläche) eintritt, wenn die Ereignisse einzeln, unabhängig voneinander und im Mittel gleich häufig auftreten. {1} zählt die Ereignisse, {2} ist ihre <3>mittlere Anzahl</3>.": "A Poisson-eloszlás azt írja le, <0>hányszor következik be egy esemény</0> rögzített idő alatt (vagy egy oldalon, egy szakaszon, egy területen), ha az események egyenként, egymástól függetlenül és átlagosan egyformán gyakran következnek be. {1} az eseményeket számolja, {2} pedig az <3>átlagos számuk</3>.",
