"Die Zufallsgrösse {0} ist hier die Auszahlung pro Spiel. Ihre <1>Wahrscheinlichkeitsverteilung</1>:": "A {0} valószínűségi változó itt az egy játékra jutó kifizetés. A <1>valószínűségeloszlása</1>:",
