"Wähle eine Funktion: Rechts wird y = {0} nach x aufgelöst, dann werden x und y vertauscht. Zur Probe ziehe {1} auf {2}: Der Spiegelpunkt {3} liegt auf {4}.": "Válassz függvényt: jobb oldalt az y = {0} egyenletet x-re rendezzük, majd felcseréljük x-et és y-t. Ellenőrzésként húzd a {1} pontot az {2} grafikonján: a {3} tükörkép az {4} grafikonján van.",
"Wähle ein Paar und ziehe den {0} auf {1}: Sein Spiegelpunkt {2} liegt auf {3} – erst f, dann f⁻¹ führt zum Ausgangswert zurück. Beachte die eingeschränkten Bereiche bei x², sin, cos und tan.": "Válassz párt; a {0} az {1} grafikonján húzható: {2} tükörképe az {3} grafikonján van – előbb f, aztán f⁻¹ visszavezet a kiindulási értékhez. Figyelj a leszűkített tartományokra x², sin, cos és tan esetén.",
"Die Winkelhalbierende y = x und die Umkehrfunktion f⁻¹ lassen sich links ein- und ausblenden.": "Az y = x szögfelező és az f⁻¹ inverz függvény bal oldalt megjeleníthető és elrejthető.",
