"<0>Bereiche tauschen:</0> Was bei {1} herauskommt (Wertebereich), darf bei {2} hinein (Definitionsbereich), und umgekehrt.": "<0>A tartományok felcserélődnek:</0> ami {1} esetén kijön (értékkészlet), az {2} esetén bemehet (értelmezési tartomány), és fordítva.",
"<0>Graph:</0> Jeder Punkt {1} auf dem Graphen von {2} wird zum Punkt {3} auf dem Graphen von {4}. Koordinaten tauschen heisst <5>Spiegeln an der Winkelhalbierenden</5> {6}.": "<0>Grafikon:</0> {2} grafikonjának minden {1} pontjából {4} grafikonjának {3} pontja lesz. A koordináták felcserélése <5>tükrözés a szögfelezőre</5>: {6}.",
"<0>Zuordnung rückwärts lesen:</0> {1} ordnet jedem {2} einen Wert {3} zu. Die <4>Umkehrfunktion</4> {5} macht das rückgängig: Sie ordnet jedem Wert {6} das ursprüngliche {7} zu. In der Wertetabelle werden dazu einfach die beiden Zeilen vertauscht.": "<0>A hozzárendelés visszafelé olvasva:</0> {1} minden {2} értékhez egy {3} értéket rendel. Az <4>inverz függvény</4> ({5}) ezt visszacsinálja: minden {6} értékhez az eredeti {7} értéket rendeli. Az értéktáblázatban ehhez csak a két sort kell felcserélni.",
