"Rechenweg: Umkehrfunktion berechnen": "Levezetés: Az inverz függvény kiszámítása",
"Die Umkehrfunktion berechnet man in drei Schritten: y = {0} nach x auflösen (Rechenschritte rückgängig machen), dann x und y vertauschen, dann Definitions- und Wertebereich tauschen.": "Az inverz függvényt három lépésben számítjuk ki: az y = {0} egyenletet x-re rendezzük (visszacsináljuk a műveleteket), aztán felcseréljük x-et és y-t, végül az értelmezési tartományt és az értékkészletet.",
