"<0>Abhilfe – Einschränkung:</0> Man lässt nur einen Ast zu, zum Beispiel {1}. Dort ist {2} streng monoton wachsend und darum umkehrbar.": "<0>Megoldás – leszűkítés:</0> csak az egyik ágat engedjük meg, például {1}. Ott {2} szigorúan monoton növekvő, ezért invertálható.",
