"Ziehe die Punkte bei x = {0} ({1}) und x = {2} ({3}): Bei jedem Schritt um {4} wird mit b multipliziert ({5}). Für b {6} {7} wächst der {8}, für {9} {10} b {11} {12} zerfällt er; vergleiche mit dem {13} – «{14} Schritt für Schritt wachsen lassen» baut beide nebeneinander auf.": "Húzd az x = {0} ({1}) és az x = {2} ({3}) helyen lévő pontot: minden {4} lépésnél b-vel szorzunk ({5}). Ha b {6} {7}, a {8} növekszik, ha {9} {10} b {11} {12}, csökken; hasonlítsd össze a {13} – a „{14} Növekedés lépésről lépésre” gomb egymás mellett építi fel a kettőt.",
