"Ziehe den {0} auf dem {1}: Die Steigung der {2} ist überall genau gleich dem Funktionswert. Bei {3} stimmt das nicht – nur die Basis e ≈ {4} hat diese Eigenschaft. «{5} Basis von {6} bis {7} gleiten lassen» hält genau dort an.": "A {0} az {1} húzható: az érintő ({2}) meredeksége mindenütt pontosan egyenlő a függvényértékkel. {3} esetén ez nem igaz – csak az e ≈ {4} alapnak van meg ez a tulajdonsága. Az „{5} Az alap csúsztatása {6}-től {7}-ig” gomb pontosan ott áll meg.",
