"Eine Zunahme um p % bedeutet Multiplikation mit q = {0} + p/{1}, eine Abnahme mit q = {2} − p/{3}. Bei mehreren Veränderungen nacheinander werden die Faktoren multipliziert, nicht die Prozente addiert. Den Grundwert findet man, indem man den neuen Wert durch den Faktor teilt.": "A p %-os növekedés q = {0} + p/{1} szorzót jelent, a csökkenés q = {2} − p/{3} szorzót. Több egymás utáni változásnál a tényezőket szorozzuk össze, nem a százalékokat adjuk össze. Az alapértéket úgy kapjuk meg, hogy az új értéket elosztjuk a tényezővel.",
"Gesamtfaktor": "összesített tényező",
