"Ziehe die {0} hoch oder runter (oder gib die Prozente ein): Jede Veränderung um p % ist eine Multiplikation mit dem {1} {2} ± p/{3}. Alle Faktoren zusammen ergeben den {4}; rückwärts teilt man den Endwert durch ihn.": "Az {0} fel-le húzhatók (vagy írd be a százalékokat): minden p %-os változás szorzás a(z) {2} ± p/{3} számmal ({1}). Az összes tényező együtt adja ezt: {4}; visszafelé a végértéket ezzel osztjuk.",
"Bei «Prozentrechnung» ziehst du die Säulen; «＋ Schritt» und «− Schritt» ändern die Anzahl Veränderungen, und du wählst vorwärts oder rückwärts.": "A „Százalékszámítás” nézetben az oszlopokat húzod; a „＋ Lépés” és a „− Lépés” a változások számát módosítja, és kiválasztod: előre vagy visszafelé.",
"Bei «Exponentialgleichungen» wählst du links eine Anwendung (Zinseszins, Zerfall, Abkühlung …) oder eine freie Gleichung; die Gerade y = c lässt sich ziehen.": "Az „Exponenciális egyenletek” nézetben bal oldalt alkalmazást (kamatos kamat, bomlás, lehűlés …) vagy szabad egyenletet választasz; az y = c egyenes húzható.",
"Die Punkte bei x = {0} (Anfangswert a) und x = {1} (Faktor b) legen die Funktion fest; «Basis e» schaltet auf die natürliche Basis um.": "Az x = {0} (a kezdőérték) és az x = {1} (b tényező) helyen lévő pontok határozzák meg a függvényt; az „e alap” a természetes alapra vált.",
