"Im rechtwinkligen Dreieck gilt bezogen auf einen spitzen Winkel α: sin α = Gegenkathete : Hypotenuse, cos α = Ankathete : Hypotenuse, tan α = Gegenkathete : Ankathete. Mit zwei bekannten Stücken (darunter eine Seite) berechnet man alle anderen; dazu kommen Pythagoras und α + β = {0}°.": "A derékszögű háromszögben az α hegyesszögre vonatkoztatva: sin α = szöggel szemközti befogó : átfogó, cos α = szög melletti befogó : átfogó, tan α = szöggel szemközti befogó : szög melletti befogó. Két ismert adatból (köztük legalább egy oldal) az összes többi kiszámítható; ehhez jön még a Pitagorasz-tétel és az α + β = {0}°.",
"Ankathete": "Szög melletti befogó",
"Gegenkathete": "Szöggel szemközti befogó",
"Ziehe die Ecken {0} und {1}: Für den Winkel {2} ist a die {3}, b die {4} und c die {5}. sin α, cos α und tan α sind ihre Verhältnisse – sie hängen nur vom Winkel ab, nicht von der Grösse des Dreiecks. Wähle oben, was gegeben ist.": "Húzd a(z) {0} és {1} csúcsot: a(z) {2} szögnél a: {3}, b: {4}, c: {5}. sin α, cos α és tan α ezek arányai – csak a szögtől függnek, a háromszög méretétől nem. Fent választhatod ki, mi adott.",
