"Im allgemeinen Dreieck gelten der Sinussatz a : sin α = b : sin β = c : sin γ und der Kosinussatz a² = b² + c² − {0}bc·cos α. Den Kosinussatz braucht man bei SSS und SWS, den Sinussatz bei WSW und SSW; bei SSW mit a {1} b kann es zwei Dreiecke geben.": "Az általános háromszögben érvényes a szinusztétel, a : sin α = b : sin β = c : sin γ, és a koszinusztétel, a² = b² + c² − {0}bc·cos α. A koszinusztételre három oldal, illetve két oldal és a közbezárt szög esetén van szükség, a szinusztételre egy oldal és két szög, illetve két oldal és egy szemközti szög esetén; az utóbbi esetben, ha a {1} b, két háromszög is lehetséges.",
"übrigen Stücke": "többi adatot",
"gegeben": "adott",
"Ziehe die Ecken {0}, {1} und {2} und wähle, was {3} ist: Die {4} berechnet der Rechenweg mit dem Sinus- oder Kosinussatz. Die Beispiele zeigen Aufgaben aus der Vermessung.": "Húzd a(z) {0}, {1} és {2} csúcsot, és válaszd ki, mi {3}: a {4} a levezetés számítja ki a szinusz- vagy a koszinusztétellel. A példák földmérési feladatokat mutatnak.",
"Bei den Dreiecken wählst du links, was gegeben ist; danach rechnet der Rechenweg mit sin, cos, tan bzw. mit dem Sinus- oder Kosinussatz.": "A háromszögeknél bal oldalon választod ki, mi adott; ezután a levezetés a sin, cos, tan segítségével, illetve a szinusz- vagy a koszinusztétellel számol.",
"Bei der allgemeinen Sinusfunktion ziehst du den Startpunkt S, den Hochpunkt H und das Periodenende; «{0} Grundfunktion verwandeln» zeigt die Schritte einzeln.": "Az általános szinuszfüggvénynél az S kezdőpontot, a H maximumpontot és a periódus végét húzhatod; a „{0} Alapfüggvény átalakítása” gomb egyenként mutatja a lépéseket.",
"«{0} Winkel drehen» lässt P auf dem Kreis laufen und zeichnet die Kurve; «⟲ φ = {1}°» setzt den Winkel zurück.": "A „{0} A szög forgatása” gomb körbefuttatja P-t a körön, és megrajzolja a görbét; a „⟲ φ = {1}°” gomb visszaállítja a szöget.",
"Winkel in Grad oder im Bogenmass: links umschalten. Die Beispiele springen zu den besonderen Winkeln ({0}°, {1}°, {2}° …).": "Szögek fokban vagy radiánban: bal oldalon váltható át. A példák a nevezetes szögekre ugranak ({0}°, {1}°, {2}° …).",
"<0>Schritt {1} – Amplitude</0> {2}: Strecken in {3}-Richtung mit dem Faktor {4}. Wegen {5} zusätzlich <6>Spiegeln an der x-Achse</6>.": "<0>{1}. lépés – amplitúdó</0> {2}: nyújtás {3} irányban, a tényező {4}. Mivel {5}, ezenkívül <6>tükrözés az x tengelyre</6>.",
