"Die allgemeine Sinusfunktion {0} = a·sin({1}) + d entsteht aus sin x: a streckt (Amplitude |a|, Hochpunkt), b ändert die Periode T = {2}π/b (Periodenende), c verschiebt in x-Richtung (Phase), d in y-Richtung (Mittellinie y = d); Startpunkt {3}.": "Az általános szinuszfüggvény, {0} = a·sin({1}) + d, a sin x-ből keletkezik: a nyújt (amplitúdó |a|, maximumpont), b a periódust változtatja meg, T = {2}π/b (periódus vége), c x irányban tol el (fázis), d y irányban (középvonal y = d); kezdőpont {3}.",
"Sinus = Höhe, Kosinus = waagrechter Abstand des Punktes {0} auf dem Einheitskreis; {1}, {2}": "Szinusz = magasság, koszinusz = a(z) {0} pont vízszintes távolsága az egységkörön; {1}, {2}",
"Dreht sich {0} gleichmässig, so beschreibt seine Höhe die Sinuskurve und sein waagrechter Abstand die Kosinuskurve – das Bild rechts.": "Ha {0} egyenletesen forog, a magassága a szinuszgörbét, a vízszintes távolsága a koszinuszgörbét írja le – ez a jobb oldali ábra.",
"<0>Periodizität und Symmetrie:</0> Eine volle Umdrehung ändert nichts; Spiegeln an der {1}-Achse lässt den Sinus gleich, Spiegeln an der {2}-Achse den Kosinus.": "<0>Periodicitás és szimmetria:</0> egy teljes körülfordulás semmit sem változtat; a(z) {1} tengelyre tükrözve a szinusz, a(z) {2} tengelyre tükrözve a koszinusz marad változatlan.",
"<0>Pythagoras im Einheitskreis:</0> Die Koordinaten von {1} sind die Katheten eines rechtwinkligen Dreiecks mit Hypotenuse {2}:": "<0>Pitagorasz-tétel az egységkörben:</0> {1} koordinátái egy olyan derékszögű háromszög befogói, amelynek átfogója {2}:",
"<0>Vorzeichen:</0> {1} liegt im {2}. Quadranten (beide positiv).": "<0>Előjelek:</0> {1} a(z) {2}. síknegyedben van (mindkettő pozitív).",
"<0>Werte bei</0> {1} (besonderer Winkel, exakte Werte aus dem halben Quadrat bzw. dem halben gleichseitigen Dreieck):": "<0>Értékek, ha</0> {1} (nevezetes szög, pontos értékek a fél négyzetből, illetve a fél szabályos háromszögből):",
"<0>Bogenmass:</0> Statt in Grad misst man den Winkel durch die <1>Länge des Bogens</1> auf dem Einheitskreis. Der ganze Kreis hat den Umfang {2}, also entspricht {3} dem Bogen {4} und {5} dem Bogen {6}.": "<0>Ívmérték:</0> fok helyett a szöget az egységkörön mért <1>ív hosszával</1> mérjük. A teljes kör kerülete {2}, ezért {3} a(z) {4} ívnek, {5} pedig a(z) {6} ívnek felel meg.",
"<0>Definition:</0> Der Kosinus ist die {1}-Koordinate von {2} (waagrechter Abstand), der Sinus die {3}-Koordinate (Höhe). Weil der Radius {4} ist, stimmt das mit Ankathete/Hypotenuse und Gegenkathete/Hypotenuse im rechtwinkligen Dreieck überein.": "<0>Definíció:</0> a koszinusz a(z) {2} pont {1}-koordinátája (vízszintes távolság), a szinusz a(z) {3}-koordinátája (magasság). Mivel a sugár {4}, ez megegyezik a derékszögű háromszögben a szög melletti befogó/átfogó, illetve a szöggel szemközti befogó/átfogó aránnyal.",
"<0>Einheitskreis:</0> Kreis mit Radius {1} um den Ursprung. Der Winkel {2} wird von der positiven {3}-Achse aus <4>gegen den Uhrzeigersinn</4> gemessen. Der Strahl trifft den Kreis im Punkt {5}.": "<0>Egységkör:</0> {1} sugarú kör az origó körül. A(z) {2} szöget a pozitív {3} tengelytől <4>az óramutató járásával ellentétes irányban</4> mérjük. A félegyenes a kört a(z) {5} pontban metszi.",
