"<0>Besondere Stellen:</0> Der erste Hochpunkt liegt bei {1}, dann alle {2}. Nullstellen (Schnitt mit der Mittellinie) liegen alle {3} auseinander.": "<0>Nevezetes helyek:</0> az első maximumpont helye {1}, a továbbiak {2} lépésenként következnek. A zérushelyek (metszéspontok a középvonallal) egymástól {3} távolságra vannak.",
