"<0>Periode:</0> Nach einer halben Drehung zeigt der Strahl in die Gegenrichtung; Sinus und Kosinus wechseln beide das Vorzeichen, ihr Quotient bleibt gleich. Der Tangens hat darum schon die Periode {1} (Sinus und Kosinus: {2}).": "<0>Periódus:</0> fél fordulat után a félegyenes az ellenkező irányba mutat; a szinusz és a koszinusz is előjelet vált, a hányadosuk változatlan marad. Ezért a tangens periódusa már {1} (a szinuszé és a koszinuszé: {2}).",
"<0>Definitionsbereich:</0> Der Tangens ist nicht definiert, wo der Kosinus {1} ist, also bei {2}, {3}, … Dort hat der Graph Polstellen.": "<0>Értelmezési tartomány:</0> a tangens nincs értelmezve ott, ahol a koszinusz {1}, vagyis a(z) {2}, {3}, … helyeken. Ott a grafikonnak pólushelye van.",
