"Werte bei": "Értékek, ha",
"<0>Definition:</0> Der Tangens ist das Verhältnis von Sinus zu Kosinus, im rechtwinkligen Dreieck also Gegenkathete durch Ankathete. Im Einheitskreis ist {1} die <2>Steigung</2> des Strahls durch {3}: Er schneidet die senkrechte Tangente bei {4} in der Höhe {5}.": "<0>Definíció:</0> a tangens a szinusz és a koszinusz hányadosa, a derékszögű háromszögben tehát a szöggel szemközti befogó osztva a szög melletti befogóval. Az egységkörben {1} a(z) {3} ponton átmenő félegyenes <2>meredeksége</2>: ez a félegyenes a(z) {4} helyen lévő függőleges érintőt {5} magasságban metszi.",
"Rechenweg: Tangens": "Levezetés: Tangens",
"Der Tangens ist das Verhältnis sin φ / cos φ – die Steigung des Strahls durch P. Am Einheitskreis liest man ihn an der senkrechten Tangente bei x = {0} ab. Wo der Kosinus {1} ist ({2}°, {3}°, …), hat der Tangens Polstellen; seine Periode ist nur π.": "A tangens a sin φ / cos φ hányados – a P-n átmenő félegyenes meredeksége. Az egységkörnél az x = {0} helyen lévő függőleges érintőn olvasható le. Ahol a koszinusz {1} ({2}°, {3}°, …), ott a tangensnek pólushelye van; a periódusa csak π.",
"<0>Lage:</0> {1} liegt auf einer Koordinatenachse; eine der beiden Koordinaten ist {2}, die andere {3}.": "<0>Helyzet:</0> {1} az egyik koordinátatengelyen van; a két koordináta közül az egyik {2}, a másik {3}.",
