"<0>Vorzeichen:</0> {1} liegt im {2}. Quadranten (Sinus negativ, Kosinus positiv).": "<0>Előjelek:</0> {1} a(z) {2}. síknegyedben van (a szinusz negatív, a koszinusz pozitív).",
