"<0>Im Bild:</0> Die Kurve mit den Punkten {1} läuft von {2} bis {3}. Die blaue Fläche zwischen Kurve und {4}-Achse ist {5}, die grüne Fläche zwischen Kurve und {6}-Achse ist {7}. Zusammen füllen sie das grosse Rechteck {8} ohne das kleine Rechteck {9}:": "<0>Az ábrán:</0> a(z) {1} pontokból álló görbe {2} és {3} között fut. A görbe és a(z) {4} tengely közötti kék terület {5}, a görbe és a(z) {6} tengely közötti zöld terület {7}. Együtt kitöltik a nagy téglalapot ({8}) a kis téglalap ({9}) nélkül:",
