"<0>Im Bild:</0> Links ist die Fläche unter {1} in gleich breite Streifen der Breite {2} geteilt. Die Abbildung {3} in der Mitte bringt jeden Streifen nach rechts unter den Graphen von {4}. Dort ist er {5}-mal so breit, aber nur {6} hoch statt {7}. Die Fläche bleibt gleich. Mit dem Regler «Verformung» sieht man den Übergang fliessend: Jeder Streifen wird {8}-mal so breit und dafür {9}-mal so niedrig.": "<0>Az ábrán:</0> bal oldalon a(z) {1} alatti terület egyenlő, {2} szélességű sávokra van osztva. A középen látható {3} leképezés minden sávot jobbra visz, {4} grafikonja alá. Ott a sáv {5}-szer olyan széles, de csak {6} magas {7} helyett. A terület ugyanakkora marad. A „Deformáció” csúszkával az átmenet folyamatosan követhető: minden sáv {8}-szer olyan széles és cserébe {9}-szer olyan alacsony lesz.",
