"Substitution: ∫ f({0}) · g′(x) dx = ∫ {1} du mit u = {2}. Links ist die Fläche von a bis b in gleich breite, farbige Streifen geteilt. In der Mitte bildet u = {3} jede Streifengrenze auf die u-Achse ab, rechts liegen dieselben Streifen unter {4}.": "Helyettesítés: ∫ f({0}) · g′(x) dx = ∫ {1} du, ahol u = {2}. Bal oldalon az a és b közötti terület egyenlő szélességű, színes sávokra van osztva. Középen u = {3} minden sávhatárt az u tengelyre képez le, jobb oldalon ugyanezek a sávok {4} alatt fekszenek.",
"Äussere Funktion f und innere Funktion g (gesucht ∫ f({0}) · g′(x) dx)": "f külső és g belső függvény (keresett: ∫ f({0}) · g′(x) dx)",
