"Ziehe den {0} oder die Grenzen {1} und {2}, oder starte die Verformung: Jeder Streifen unter {3} wird über {4} zu einem Streifen unter {5} – g′(x)-mal so breit, g′(x)-mal so niedrig, gleiche Fläche.": "Húzd a {0} vagy az {1} és {2} határt, vagy indítsd el a deformációt: a(z) {3} alatti minden sávból {4} révén egy {5} alatti sáv lesz – g′(x)-szer olyan széles, g′(x)-szer olyan alacsony, ugyanakkora területű.",
"Die Fläche zwischen f und der x-Achse (oder zwischen f und g) von a bis b wird an den Schnittstellen in Stücke geteilt. Stücke über der Achse (bzw. über g) sind grün, darunter orange.": "Az f és az x tengely (vagy f és g) közötti területet a-tól b-ig a metszéspontoknál részekre osztjuk. A tengely (illetve g) fölötti részek zöldek, az alatta lévők narancssárgák.",
"Ziehe {0} und {1} (oder wähle «zwischen f und g»): Die Fläche zwischen {2} und der x-Achse bzw. {3} wird an den Schnittstellen geteilt – Stücke darüber sind grün, darunter orange. Flächen zählen immer positiv.": "Húzd az {0} és a {1} határt (vagy válaszd az „f és g között” lehetőséget): a(z) {2} és az x tengely, illetve {3} közötti területet a metszéspontoknál felosztjuk – a fölötte lévő részek zöldek, az alatta lévők narancssárgák. A területek mindig pozitívnak számítanak.",
"{0} Graph drehen, dann Scheiben": "{0} Grafikon forgatása, utána korongok",
"Dreht man den Graphen von f zwischen a und b um die x-Achse, entsteht ein Körper aus lauter dünnen Kreisscheiben. Jede Scheibe hat das Volumen π · {0}² · Δx.": "Ha f grafikonját a és b között megforgatjuk az x tengely körül, csupa vékony korongból álló test keletkezik. Minden korong térfogata π · {0}² · Δx.",
