"Ziehe {0} und {1} und erhöhe die Zahl der {2} (oder starte «{3} Graph drehen, dann Scheiben»): Der {4} dreht sich um die x-Achse, jede Scheibe hat das Volumen π·{5}²·Δx, und ihre Summe nähert sich V = π ∫ {6}² dx.": "Húzd az {0} és a {1} határt, és növeld a darabszámot ({2}) (vagy indítsd el: „{3} Grafikon forgatása, utána korongok”): {4} forog az x tengely körül, minden korong térfogata π·{5}²·Δx, és összegük V = π ∫ {6}² dx értékéhez közelít.",
"Partielle Integration und Substitution sind als Bild erklärt: Punkte und Grenzen ziehen, bei der Substitution «{0} Streifen in die u-Welt verformen».": "A parciális integrálást és a helyettesítést ábra magyarázza: húzd a pontokat és a határokat, a helyettesítésnél használd a „{0} Sávok átalakítása az u-világba” gombot.",
"Flächen: Links wählst du, ob die Fläche zur x-Achse oder zwischen f und g gesucht ist; «Grenzen auf die Nullstellen setzen» hilft beim Start.": "Területek: bal oldalon választod ki, hogy az x tengelyig vagy az f és g közötti terület a keresett; a „Határok beállítása a zérushelyekre” gomb segít az induláskor.",
"Integralfunktion und Hauptsatz: Ein Klick ins Bild setzt die Stelle x, an der gestrichelten Linie lässt sie sich ziehen. Ziehen im Bild verschiebt den Ausschnitt (oben f, unten Fa getrennt), das Mausrad bzw. zwei Finger zoomen; Doppelklick oder «⟲ Ausschnitt» stellt den automatischen Ausschnitt wieder her.": "Integrálfüggvény és alaptétel: az ábrába kattintva beállítható az x hely, a szaggatott vonalnál fogva pedig húzható. Az ábrában húzva a kivágás mozdul el (fent f, lent Fa külön), az egérgörgő vagy két ujj nagyít; dupla kattintás vagy a „⟲ Kivágás” gomb visszaállítja az automatikus kivágást.",
"Ober- und Untersumme: Anzahl n links erhöhen oder «{0} n → ∞» starten; «n = {1}» setzt zurück.": "Felső és alsó összeg: növeld bal oldalon az n számot, vagy indítsd el: „{0} n → ∞”; az „n = {1}” gomb visszaállít.",
"Die Grenzen a und b ziehst du auf der x-Achse; eine eigene Funktion tippst du ins Feld.": "Az a és b határt az x tengelyen húzhatod; saját függvényt a mezőbe írhatsz be.",
"Untersumme zeigen (grün)": "Alsó összeg mutatása (zöld)",
"Mit den Grundregeln findet das Programm hier keine Stammfunktion (partielle Integration oder Substitution nötig, oder es gibt keine geschlossene Form); die Integralfunktion wird numerisch berechnet.": "Az alapszabályokkal a program itt nem talál primitív függvényt (parciális integrálás vagy helyettesítés kellene, vagy nincs zárt alak); az integrálfüggvényt numerikusan számoljuk.",
