"Mit den Grundregeln (Potenz-, Summen-, Konstantenregel) findet das Programm hier keine Stammfunktion: Dafür bräuchte es partielle Integration oder Substitution, bei manchen Funktionen gibt es gar keine geschlossene Form. Das Integral wird numerisch berechnet.": "Az alapszabályokkal (hatvány-, összeg- és konstansszabály) a program itt nem talál primitív függvényt: ehhez parciális integrálás vagy helyettesítés kellene, és egyes függvényeknek egyáltalán nincs zárt alakja. Az integrált numerikusan számoljuk.",
"Mit den Grundregeln (Potenz-, Summen-, Konstantenregel) findet das Programm hier keine Stammfunktion: Dafür bräuchte es partielle Integration oder Substitution (siehe die Ansichten dazu); bei manchen Funktionen wie {0} gibt es gar keine geschlossene Form. Das bestimmte Integral wird numerisch berechnet.": "Az alapszabályokkal (hatvány-, összeg- és konstansszabály) a program itt nem talál primitív függvényt: ehhez parciális integrálás vagy helyettesítés kellene (lásd a megfelelő nézeteket); egyes függvényeknek, például ennek: {0}, egyáltalán nincs zárt alakja. A határozott integrált numerikusan számoljuk.",
