"Oben der Graph von f, unten der Graph der Ableitung f′. Ziehe den Punkt: Die Höhe des unteren Punktes ist die Steigung der Tangente oben. Der Ausschnitt richtet sich nach den Nullstellen, Extrem- und Wendepunkten. Ziehen im Bild verschiebt ihn, Mausrad oder zwei Finger zoomen, ein Klick setzt die Stelle; «⟲ Ausschnitt» stellt ihn wieder her.": "Fent f grafikonja, lent az f′ derivált grafikonja. Húzd a pontot: az alsó pont magassága a felső érintő meredeksége. A kivágás a zérushelyekhez, a szélsőértékekhez és az inflexiós pontokhoz igazodik. Az ábrában húzva elmozdul, az egérgörgő vagy két ujj nagyít, egy kattintás beállítja a helyet; a „⟲ Kivágás” gomb visszaállítja.",
"Hoch-, Tief- und Wendepunkten": "maximum-, minimum- és inflexiós pontoknál",
"Ziehe den {0} entlang von {1} oder lass die Tangente wandern: Die Steigung der {2} oben ist die Höhe des Punktes auf {3} unten. An {4} rastet der Punkt ein, und die Animation wartet, bis du «{5} weiter» drückst.": "A {0} húzható {1} mentén, vagy futtasd végig az érintőt: a fenti egyenes ({2}) meredeksége a lenti, {3} grafikonján lévő pont magassága. A {4} a pont megáll, és az animáció megvárja, amíg megnyomod a „{5} tovább” gombot.",
"An dieser Stelle ist die Funktion nicht definiert oder nicht ableitbar.": "Ezen a helyen a függvény nincs értelmezve vagy nem deriválható.",
"Normale": "Normális",
"Gib eine Funktion ein und ziehe den {0} auf dem {1}: Rechts wird f′(x) mit den Ableitungsregeln berechnet, daraus die Steigung und die Gleichung der {2} in P (optional auch {3} und {4}).": "Adj meg egy függvényt; a {0} a görbén ({1}) húzható: jobb oldalon a deriválási szabályokkal kiszámítható f′(x), ebből pedig a P-beli egyenes ({2}) meredeksége és egyenlete (választhatóan {3} és {4} is).",
"Gib eine Funktion ein oder wähle ein Beispiel: Am {0} sind {1}, {2} und {3} markiert, rechts stehen alle Ergebnisse. Der Rechenweg zeigt Schritt für Schritt, wie man sie findet.": "Adj meg egy függvényt, vagy válassz példát: a görbén ({0}) meg vannak jelölve ezek: {1}, {2} és {3}; jobb oldalon áll minden eredmény. A levezetés lépésről lépésre megmutatja, hogyan találhatók meg.",
