"Extremwertprobleme löst man in fünf Schritten: Variable wählen, Nebenbedingung aufstellen, Zielfunktion mit nur einer Variablen und Definitionsbereich angeben, Ableitung null setzen, Art des Extremums prüfen und das Ergebnis deuten.": "A szélsőérték-feladatokat öt lépésben oldjuk meg: változó választása, a mellékfeltétel felírása, az egyváltozós célfüggvény és értelmezési tartományának megadása, a derivált nullával egyenlővé tétele, a szélsőérték fajtájának ellenőrzése és az eredmény értelmezése.",
"Optimum": "optimum",
"Wähle eine Situation und ziehe den {0} auf der {1} (oder ändere x): Das {2} zeigt die Figur zur Variablen {3}. Wo die {4} waagrecht wird, liegt das {5}. «{6} x durchlaufen lassen» fährt alle Möglichkeiten ab und zeichnet dabei die Zielfunktion.": "Válassz helyzetet; a {0} a görbén ({1}) húzható, vagy módosítsd x-et: az {2} a(z) {3} változóhoz tartozó alakzatot mutatja. Ahol az egyenes ({4}) vízszintes lesz, ott van az {5}. A „{6} x végigfuttatása” gomb minden lehetőséget bejár, és közben megrajzolja a célfüggvényt.",
