"Grad des Polynoms": "A polinom fokszáma",
"Ein Polynom vom Grad n hat n + {0} Koeffizienten. Jede Bedingung (Punkt, Steigung, Extremum f′ = {1}, Wendepunkt f″ = {2}) liefert eine lineare Gleichung; das Gleichungssystem bestimmt die Koeffizienten.": "Egy n-edfokú polinomnak n + {0} együtthatója van. Minden feltétel (pont, meredekség, szélsőérték f′ = {1}, inflexiós pont f″ = {2}) egy lineáris egyenletet ad; az egyenletrendszer meghatározza az együtthatókat.",
