"Steigungen": "Meredekségek",
"Lege den Grad fest und gib die Bedingungen an – {0} oder {1} – und ziehe sie im Bild: Sobald es gleich viele Gleichungen wie Unbekannte sind, erscheint das {2}.": "Állítsd be a fokszámot, add meg a feltételeket – {0} vagy {1} –, és húzd őket az ábrán: amint ugyanannyi az egyenlet, mint az ismeretlen, megjelenik a {2}.",
"Polynom aus Bedingungen: Mit «＋ Bedingung» gibst du Punkte, Extrem- und Wendepunkte oder Steigungen vor und ziehst sie im Bild.": "Polinom feltételekből: a „＋ Feltétel” gombbal pontokat, szélsőérték- és inflexiós pontokat vagy meredekségeket adsz meg, és az ábrán húzhatod őket.",
"Kurvendiskussion: «Färbung von f» zeigt Steigen und Fallen oder die Krümmung; f′ und f″ lassen sich einzeichnen.": "Függvényvizsgálat: az „f színezése” a növekedést és csökkenést vagy a görbületet mutatja; f′ és f″ berajzolható.",
"Graphisches Ableiten: Ein Klick setzt die Stelle, Ziehen verschiebt den Ausschnitt, an der gestrichelten Linie ziehst du den Punkt. Der Ausschnitt richtet sich nach der Funktion; «⟲ Ausschnitt» stellt ihn wieder her. Mit «f′ verstecken» skizzierst du die Ableitung selbst.": "Grafikus deriválás: egy kattintás beállítja a helyet, húzással a kivágás mozdul el, a pontot a szaggatott vonalnál fogva húzhatod. A kivágás a függvényhez igazodik; a „⟲ Kivágás” gomb visszaállítja. Az „f′ elrejtése” beállítással önállóan vázolhatod fel a deriváltat.",
"Sekante → Tangente: Q zu P ziehen oder «{0} h → {1}» drücken; «h = {2}» stellt den Abstand wieder her. Links wählst du, ob Q rechts oder links von P liegt.": "Szelő → érintő: húzd Q-t P-hez, vagy nyomd meg: „{0} h → {1}”; a „h = {2}” gomb visszaállítja a távolságot. Bal oldalon választod ki, hogy Q a P-től jobbra vagy balra legyen.",
"Eigene Funktion ins Feld «{0} =» tippen und «Übernehmen»; die Stelle x₀ ziehst du im Bild oder änderst sie links mit {1} {2}.": "Saját függvényt az „{0} =” mezőbe írhatsz, majd nyomd meg az „Alkalmaz” gombot; az x₀ helyet az ábrán húzhatod, vagy bal oldalon a {1} {2} gombokkal módosíthatod.",
"Sekante, Tangente, h-Methode": "Szelő, érintő, h-módszer",
"Für diese Funktion wird der Grenzwert mit einer Zahlenreihe von links und von rechts geschätzt.": "Ennél a függvénynél a határértéket balról és jobbról vett értéksorral becsüljük.",
"Links- und rechtsseitiger Grenzwert sind unendlich: Polstelle, der Grenzwert existiert nicht.": "A bal és a jobb oldali határérték végtelen: pólushely, a határérték nem létezik.",
"Der Nenner wird {0}, der Zähler nicht: <1>Polstelle</1>. Die Funktionswerte wachsen dem Betrag nach über alle Grenzen.": "A nevező {0} lesz, a számláló nem: <1>pólushely</1>. A függvényértékek abszolút értéke minden határon túl nő.",
