"Bei einer geometrischen Folge ist der Quotient q benachbarter Glieder (a₁, a₂) konstant: aₙ = a₁·qⁿ⁻¹. Für q {0} {1} exponentielles Wachstum, für {2} {3} q {4} {5} Zerfall.": "A mértani sorozatban a szomszédos tagok (a₁, a₂) q hányadosa állandó: aₙ = a₁·qⁿ⁻¹. Ha q {0} {1}, exponenciális növekedés, ha {2} {3} q {4} {5}, csökkenés.",
