"Das Summenzeichen ist eine Kurzschrift: ∑ von k = m bis n über aₖ bedeutet aₘ + aₘ₊₁ + … + aₙ. Die Laufvariable (meist k, i oder j) durchläuft alle ganzen Zahlen von der unteren bis zur oberen Grenze; es gibt n − m + {0} Summanden. Der Name der Laufvariablen spielt keine Rolle, und man kann den Index verschieben: ∑ von k = {1} bis {2} über (k − {3}) = ∑ von j = {4} bis {5} über j.": "Az összegjel rövidítés: ∑ (k = m … n) aₖ azt jelenti: aₘ + aₘ₊₁ + … + aₙ. A futóindex (többnyire k, i vagy j) az alsó határtól a felső határig minden egész számot felvesz; n − m + {0} összeadandó van. A futóindex neve nem számít, és az index eltolható: ∑ (k = {1} … {2}) (k − {3}) = ∑ (j = {4} … {5}) j.",
