"Lies das Summenzeichen: Die {0} sagt, bei welchem k du beginnst, die {1}, wo du aufhörst. Den {2} rechnest du für jedes k aus und addierst alle. Ziehe im Bild die Grenzen m und n und die {3}: Der Balken von k leuchtet, oben steht sein Summand. «{4} k von m bis n laufen lassen» addiert die Summanden der Reihe nach.": "Olvasd el az összegjelet: az {0} megmondja, melyik k-nál kezdesz, a {1}, hogy hol fejezed be. Az {2} értékét minden k-ra kiszámítod, és mindet összeadod. Az ábrán húzható az m és n határ, valamint a {3}: a k-hoz tartozó oszlop kivilágosodik, fölötte az összeadandója áll. A „{4} k végigfuttatása m-től n-ig” gomb sorban összeadja az összeadandókat.",
"<0>Trick von Gauss:</0> Die Summe vorwärts und rückwärts untereinander schreiben. Jede Spalte ergibt {1}, und es gibt {2} Spalten: {3}.": "<0>Gauss trükkje:</0> az összeget előre és visszafelé egymás alá írjuk. Minden oszlop összege {1}, és {2} oszlop van: {3}.",
