"Die Summe der ersten n Glieder heisst Reihe: sₙ = a₁ + … + aₙ. Arithmetisch: sₙ = n·(a₁ + aₙ)/{0} (Trick von Gauss), geometrisch: sₙ = a₁·(qⁿ − {1})/(q − {2}).": "Az első n tag összegét sornak nevezzük: sₙ = a₁ + … + aₙ. Számtani: sₙ = n·(a₁ + aₙ)/{0} (Gauss trükkje), mértani: sₙ = a₁·(qⁿ − {1})/(q − {2}).",
