"Ziehe den {0} im unteren Bild nach links oder rechts, um n zu ändern: Oben kommen {1} dazu oder fallen weg, unten wächst sₙ = a₁ + … + aₙ. Beim Gauss-Trick ergänzt die rückwärts gelesene Folge die Balken zu einem Rechteck («{2} Gauss-Trick als Bewegung» zeigt, wie sie sich umdreht).": "Húzd a {0} az alsó ábrán balra vagy jobbra, hogy n megváltozzon: fent {1} adódnak hozzá vagy tűnnek el, lent sₙ = a₁ + … + aₙ növekszik. A Gauss-trükknél a visszafelé olvasott sorozat téglalappá egészíti ki az oszlopokat (a „{2} Gauss-trükk mozgásként” gomb megmutatja, hogyan fordul meg).",
