"Kommen die Glieder für grosse n einer Zahl beliebig nahe, ist das der Grenzwert. Zu jedem ε gibt es ein N, ab dem alle Glieder im ε-Streifen liegen. Eine unendliche geometrische Reihe hat für |q| {0} {1} den Wert a₁/({2} − q).": "Ha a tagok nagy n-re tetszőlegesen megközelítenek egy számot, akkor ez a szám a határérték. Minden ε-hoz van olyan N, amelytől kezdve minden tag az ε-sávban van. A végtelen mértani sor értéke |q| {0} {1} esetén a₁/({2} − q).",
