"Ziehe den {0}, um den {1} um den {2} schmaler zu machen: Ab einem Index N liegen alle Glieder im Streifen – je kleiner ε, desto weiter rechts liegt N. Mit «{3} Animation: ε → {4}» wird der Streifen immer schmaler, und es kommen immer mehr Glieder dazu.": "Húzd a {0}, hogy a határérték ({2}) körüli sáv ({1}) keskenyebb legyen: egy N indextől kezdve minden tag a sávban van – minél kisebb ε, annál jobbra van N. Az „{3} Animáció: ε → {4}” gombbal a sáv egyre keskenyebb lesz, és egyre több tag jelenik meg.",
