"Vollständige Induktion: Gilt die Aussage für n = {0} (Anfang) und folgt sie für n + {1}, wenn sie für n gilt (Schritt), dann gilt sie für alle n – wie bei fallenden Dominosteinen.": "Teljes indukció: ha az állítás n = {0} esetén igaz (kezdet), és az n + {1} esetre következik, valahányszor n-re igaz (lépés), akkor minden n-re igaz – mint a ledőlő dominóknál.",
"Wähle eine Aussage und lass mit «Schritt» die Dominosteine fallen: Gilt {0} und folgt aus {1} stets {2}, dann gilt die Aussage für alle n. Die letzte Aussage zeigt, warum Beispiele allein nichts beweisen.": "Válassz állítást, és a „Lépés” gombbal döntsd le a dominókat: ha {0} igaz, és ha {1} mindig maga után vonja ezt: {2}, akkor az állítás minden n-re igaz. Az utolsó állítás megmutatja, miért nem bizonyítanak semmit a példák önmagukban.",
