"Die Reihe rückwärts darunter schreiben: Jede Spalte ergibt {0}, und es sind {1} Spalten. Das ist die Summe zweimal, also s = {2} · {3} / {4}. Dieselbe Idee steckt in der Formel sₙ = n · (a₁ + aₙ) / {5}.": "A sort visszafelé alá írjuk: minden oszlop összege {0}, és {1} oszlop van. Ez az összeg kétszerese, tehát s = {2} · {3} / {4}. Ugyanez az ötlet rejlik az sₙ = n · (a₁ + aₙ) / {5} képletben.",
"Der Legende nach stellte der Lehrer Büttner um {0} seiner Klasse die Aufgabe, alle Zahlen von {1} bis {2} zu addieren – er wollte eine Weile Ruhe. Der neunjährige Carl Friedrich Gauss war nach wenigen Augenblicken fertig:": "A legenda szerint Büttner tanító {0} körül azt a feladatot adta az osztályának, hogy adják össze az összes számot {1} és {2} között – egy kis nyugalmat akart. A kilencéves Carl Friedrich Gauss néhány pillanat alatt elkészült:",
