"Ein <0>Intervall</0> ist die Menge aller reellen Zahlen zwischen zwei Randpunkten. Eckige Klammer {1}: Randpunkt gehört dazu; runde Klammer {2}: gehört nicht dazu. Bei {3} ist die Klammer immer offen.": "Az <0>intervallum</0> a két végpont közötti összes valós szám halmaza. Szögletes zárójel {1}: a végpont hozzátartozik; kerek zárójel {2}: nem tartozik hozzá. {3} esetén a zárójel mindig nyílt.",
