"{0} Ziehe die Randpunkte im Bild. Links wählst du offen oder geschlossen, unendlich und die Operation; rechts steht der Rechenweg.": "{0} Húzd a végpontokat az ábrán. Bal oldalon választod ki, hogy nyílt vagy zárt, végtelen-e, valamint a műveletet; jobb oldalon áll a levezetés.",
