"<0>Vorgehen:</0> Beide Intervalle untereinander auf der Zahlengeraden einzeichnen, die gesuchten Bereiche ablesen und bei jedem Randpunkt prüfen, ob er dazugehört.": "<0>Eljárás:</0> a két intervallumot egymás alá rajzoljuk a számegyenesen, leolvassuk a keresett részeket, és minden végpontnál ellenőrizzük, hogy hozzátartozik-e.",
