"Operation": "Művelet",
"Mit Intervallen rechnet man wie mit Mengen: A ∩ B (und), A ∪ B (oder), A \\ B (ohne) und das Komplement Ā (alle anderen reellen Zahlen). Am einfachsten zeichnet man beide Intervalle untereinander und liest das Ergebnis ab; an jedem Randpunkt entscheidet man, ob er dazugehört.": "Az intervallumokkal ugyanúgy számolunk, mint a halmazokkal: A ∩ B (és), A ∪ B (vagy), A \\ B (nélkül) és az Ā komplementer (az összes többi valós szám). A legegyszerűbb, ha a két intervallumot egymás alá rajzoljuk, és leolvassuk az eredményt; minden végpontnál eldöntjük, hogy hozzátartozik-e.",
"Ergebnismenge": "eredményhalmaz",
"Ziehe die Randpunkte von {0} und {1} und wähle eine Operation: Die {2} zeigt, welche Zahlen in A und B liegen (Schnittmenge), in A oder B (Vereinigung), in A, aber nicht in B (Differenz) oder nicht in A (Komplement).": "Húzd az {0} és a {1} végpontjait, és válassz műveletet: az {2} megmutatja, mely számok vannak A-ban és B-ben (metszet), A-ban vagy B-ben (unió), A-ban, de B-ben nem (különbség), vagy nincsenek A-ban (komplementer).",
