"Vereinigung A ∪ B: in A oder B. Schnitt A ∩ B: in A und B. Differenz A \\ B: in A, aber nicht in B. Komplement Ā: in G, aber nicht in A. Bei drei Mengen gibt es acht Felder; man füllt sie von der Mitte nach aussen. Gesetze von De Morgan: (A ∪ B)‾ = Ā ∩ B̄ und (A ∩ B)‾ = Ā ∪ B̄.": "Unió A ∪ B: A vagy B eleme. Metszet A ∩ B: A és B eleme. Különbség A \\ B: A eleme, de B-nek nem. Komplementer Ā: G eleme, de A-nak nem. Három halmaznál nyolc tartomány van; ezeket középről kifelé töltjük ki. De Morgan-azonosságok: (A ∪ B)‾ = Ā ∩ B̄ és (A ∩ B)‾ = Ā ∪ B̄.",
