"Tipp: Zuerst die Klammern. Ein Feld gehört dazu, wenn seine Punkte die Bedingung erfüllen.": "Tipp: először a zárójelek. Egy tartomány akkor tartozik a halmazhoz, ha a pontjai teljesítik a feltételt.",
