"Venn-Diagramm": "Venn-diagram",
"Wähle links die Aufgabenart und löse die Aufgabe: Tippe die Antwort ein oder klicke im {0} die Felder an, die zur Menge gehören. «Prüfen» zeigt, ob es stimmt; danach steht rechts der Lösungsweg.": "Válaszd ki bal oldalon a feladattípust, és oldd meg a feladatot: írd be a választ, vagy kattints az ábrán ({0}) a halmazhoz tartozó tartományokra. Az „Ellenőrzés” megmutatja, helyes-e; utána jobb oldalon áll a megoldás.",
