"Gib links eine {0} in Koordinatenform ein (z. B. {1}x + {2}y − z = {3}) und drehe den Raum mit der Maus: {4} und {5} zeigen, wo sie die Achsen und Koordinatenebenen trifft. Mit zwei oder drei Ebenen erscheinen {6} und {7}.": "Adj meg bal oldalon egy egyenletet általános alakban ({0}), pl. {1}x + {2}y − z = {3}, és forgasd a teret az egérrel: {4} és {5} megmutatja, hol metszi a sík a tengelyeket és a koordinátasíkokat. Két vagy három sík esetén megjelenik: {6} és {7}.",
"{0} Ziehe im Bild, um den Raum zu drehen; oben links wählst du die Ansicht, rechts steht der Rechenweg.": "{0} Az ábrában húzva forgathatod a teret; bal felül választod ki a nézetet, jobb oldalon áll a levezetés.",
