"Ein Punkt {0} hat den Ortsvektor OA. Der Verbindungsvektor ist AB = B − A (Spitze minus Fuss). Seine Länge |AB| = √(v₁² + v₂² + v₃²) ist der Abstand der Punkte, der Mittelpunkt ist M = ½(A + B).": "A(z) {0} pont helyvektora OA. Az összekötő vektor AB = B − A (végpont mínusz kezdőpont). Hossza, |AB| = √(v₁² + v₂² + v₃²), a pontok távolsága; a felezőpont M = ½(A + B).",
