"Gib links die Geraden g und h in Parameterform ein und drehe den Raum: Schneiden sie sich im {0}, sind sie parallel oder {1}? Die {2} entscheiden zuerst. Mit den Reglern t und s (oder «{3} t und s laufen lassen») wandern die Punkte {4} und {5} auf den Geraden: Jeder Parameterwert gibt genau einen Punkt.": "Add meg bal oldalon a g és h egyenest paraméteres alakban, és forgasd a teret: van közös pontjuk ({0}), párhuzamosak vagy {1}? Először az {2} döntenek. A t és s csúszkával (vagy a „{3} t és s végigfuttatása” gombbal) a(z) {4} és {5} pont végigmegy az egyeneseken: minden paraméterérték pontosan egy pontot ad.",
"Gerade in Parameterform: X = P + t·u mit Stützpunkt P und Richtungsvektor u. Zwei Geraden sind identisch, echt parallel, schneidend oder windschief. Prüfen: Sind u und v Vielfache? Sonst gleichsetzen: zwei Gleichungen lösen, die dritte prüfen.": "Egyenes paraméteres alakban: X = P + t·u, ahol P a támaszpont és u az irányvektor. Két egyenes egybeesik, párhuzamos (különböző), metsző vagy kitérő. Ellenőrizni: többszörösei-e egymásnak u és v? Ha nem, egyenlővé tenni: két egyenletet megoldani, a harmadikat ellenőrizni.",
