"Vektorprodukt: a = ({0} | {1} | {2}), b = ({3} | {4} | {5})": "Vektoriális szorzat: a = ({0} | {1} | {2}), b = ({3} | {4} | {5})",
"Stumpfer Winkel: a = ({0} | {1} | {2}), b = (−{3} | {4} | {5})": "Tompaszög: a = ({0} | {1} | {2}), b = (−{3} | {4} | {5})",
"Senkrecht: a = ({0} | {1} | −{2}), b = ({3} | {4} | {5})": "Merőlegesek: a = ({0} | {1} | −{2}), b = ({3} | {4} | {5})",
