"Gib links die Vektoren a und b ein und drehe den Raum: Der {0} zwischen ihnen folgt aus dem Skalarprodukt. Ist a · b = {1}, stehen sie senkrecht. Das {2} steht senkrecht auf beiden.": "Add meg bal oldalon az a és b vektort, és forgasd a teret: a köztük lévő {0} a skaláris szorzatból adódik. Ha a · b = {1}, merőlegesek. Az {2} mindkettőre merőleges.",
"Skalarprodukt: a · b = a₁b₁ + a₂b₂ + a₃b₃ = |a|·|b|·cos φ. Daraus der Winkel: cos φ = a · b / (|a|·|b|). Senkrecht genau dann, wenn a · b = {0}. Vektorprodukt a × b: senkrecht zu a und b, Länge = Fläche des Parallelogramms.": "Skaláris szorzat: a · b = a₁b₁ + a₂b₂ + a₃b₃ = |a|·|b|·cos φ. Ebből a szög: cos φ = a · b / (|a|·|b|). Pontosan akkor merőlegesek, ha a · b = {0}. Vektoriális szorzat a × b: merőleges a-ra és b-re, hossza = a paralelogramma területe.",
"<0>Lotfusspunkt:</0> Vom Punkt {1} aus in Richtung {2} bis zur Ebene: {3}.": "<0>A merőleges talppontja:</0> a(z) {1} pontból {2} irányban a síkig: {3}.",
