"Gib links den Punkt X und die Ebene oder Gerade ein und drehe den Raum: Der {0} ist die Länge des Lots vom Punkt X zum {1}.": "Add meg bal oldalon az X pontot és a síkot vagy az egyenest, és forgasd a teret: a {0} az X pontból bocsátott merőleges hossza; a merőleges végpontja az {1}.",
"Abstand Punkt–Ebene mit der Hesseschen Normalform: d = |a·x₀ + b·y₀ + c·z₀ − d| / |n|. Abstand Punkt–Gerade: Lotfusspunkt F auf der Geraden so, dass XF senkrecht zum Richtungsvektor steht, dann d = |XF|.": "Pont–sík távolság a Hesse-féle normálalakkal: d = |a·x₀ + b·y₀ + c·z₀ − d| / |n|. Pont–egyenes távolság: az F talppont az egyenesen úgy, hogy XF merőleges legyen az irányvektorra; ekkor d = |XF|.",
