"Gib links Mittelpunkt und Radius ein und drehe den Raum: Liegt der {0} innen, auf oder ausserhalb der {1}? Die {2} schneidet sie in einem {3}, berührt sie oder verfehlt sie.": "Add meg bal oldalon a középpontot és a sugarat, és forgasd a teret: az {0} belül, a felületen vagy kívül van ({1})? A {2} metszi – ekkor {3} keletkezik –, érinti vagy elkerüli.",
"Kugel mit Mittelpunkt {0} und Radius r: (x − m₁)² + (y − m₂)² + (z − m₃)² = r². Lage eines Punktes: Abstand zu M mit r vergleichen. Lage einer Ebene: Abstand d von M zur Ebene; für d {1} r Schnittkreis mit Radius √(r² − d²).": "{0} középpontú, r sugarú gömb: (x − m₁)² + (y − m₂)² + (z − m₃)² = r². Pont helyzete: az M-től mért távolságot összehasonlítjuk r-rel. Sík helyzete: M távolsága a síktól d; ha d {1} r, a metszetkör sugara √(r² − d²).",
"In den anderen Ansichten gibst du Punkte, Vektoren und Geraden links als Koordinaten ein; die Beispiele füllen die Felder aus.": "A többi nézetben bal oldalon koordinátákkal adod meg a pontokat, vektorokat és egyeneseket; a példák kitöltik a mezőket.",
"Ebenen entdecken: Gleichung eintippen und «+ Ebene». Buchstaben wie a, b, c, d in der Gleichung werden zu Schiebereglern.": "Síkok felfedezése: írj be egy egyenletet, majd „+ Sík”. Az egyenletben szereplő betűkből (a, b, c, d) csúszkák lesznek.",
"«Von oben», «Von vorn» und «Von der Seite» zeigen die Risse; «Bereich ±» legt fest, wie weit die Achsen reichen.": "A „Felülnézet”, az „Elölnézet” és az „Oldalnézet” a vetületeket mutatja; a „Tartomány ±” megadja, meddig érnek a tengelyek.",
"Raum drehen: im Bild ziehen. Mausrad zoomt, Umschalt+Ziehen verschiebt, Doppelklick stellt die Standardansicht her.": "A tér forgatása: húzd az ábrában. Az egérgörgő nagyít, a Shift+húzás eltol, a dupla kattintás visszaállítja az alapnézetet.",
