"Für {0} ist kein Winkel festgelegt.": "{0} esetén a szög nincs meghatározva.",
"Mit diesen Werten lässt sich kein Bild zeichnen.": "Ezekkel az értékekkel nem rajzolható ábra.",
"Eine komplexe Zahl z = a + bi besteht aus zwei reellen Zahlen: dem Realteil a und dem Imaginärteil b. Die imaginäre Einheit i erfüllt i² = −{0}. Man zeichnet z als Punkt (a | b) oder als Zeiger vom Ursprung aus. Die Polarform beschreibt denselben Punkt durch Betrag und Winkel.": "A z = a + bi komplex szám két valós számból áll: az a valós részből és a b képzetes részből. Az i képzetes egységre i² = −{0}. A z számot az (a | b) pontként vagy az origóból induló nyílként ábrázoljuk. A trigonometrikus alak ugyanazt a pontot abszolút értékkel és szöggel írja le.",
"Gauss-Ebene mit Betrag und Argument, Addieren und Subtrahieren als Zeiger, Multiplizieren und Dividieren als Drehstreckung, Potenzen (Moivre), Wurzeln und Einheitswurzeln, quadratische Gleichungen mit komplexen Lösungen": "Gauss-sík abszolút értékkel és argumentummal, összeadás és kivonás nyilakkal, szorzás és osztás mint forgatva nyújtás, hatványok (Moivre), gyökök és egységgyökök, másodfokú egyenletek komplex megoldásokkal",
