"Ist die Diskriminante negativ, zieht man die Wurzel mit Hilfe der imaginären Einheit. Jede quadratische Gleichung mit reellen Koeffizienten hat damit zwei Lösungen (oder eine doppelte). Die Sätze von Vieta für Summe und Produkt der Lösungen gelten weiter.": "Ha a diszkrimináns negatív, a gyökvonást a képzetes egység segítségével végezzük el. Így minden valós együtthatós másodfokú egyenletnek két megoldása van (vagy egy kétszeres). A megoldások összegére és szorzatára vonatkozó Viète-formulák továbbra is érvényesek.",
"Aus der Formel von Moivre folgt: Alle n-ten Wurzeln von w haben denselben Betrag, und ihre Winkel unterscheiden sich um den n-ten Teil des Vollwinkels. Für w = {0} heissen sie Einheitswurzeln.": "A Moivre-képletből következik: w összes n-edik gyökének ugyanakkora az abszolút értéke, a szögeik pedig a teljesszög n-ed részével térnek el egymástól. Ha w = {0}, egységgyököknek nevezzük őket.",
"Formel von Moivre: Die n-te Potenz hat den n-fachen Winkel, und ihr Betrag ist die n-te Potenz des Betrags. Ist der Betrag grösser als {0}, laufen die Potenzen auf einer Spirale nach aussen, ist er kleiner als {1}, nach innen.": "Moivre-képlet: az n-edik hatvány szöge n-szeres, abszolút értéke pedig az abszolút érték n-edik hatványa. Ha az abszolút érték nagyobb, mint {0}, a hatványok spirálban kifelé haladnak; ha kisebb, mint {1}, befelé.",
"Gerechnet wird wie mit Klammern, mit i² = −{0}. In der Polarform ist das Produkt eine Drehstreckung: Beträge multiplizieren, Winkel addieren. Beim Dividieren ist es umgekehrt: Beträge dividieren, Winkel subtrahieren; in der Normalform erweitert man mit der konjugierten Zahl des Nenners.": "Úgy számolunk, mint zárójelekkel, és felhasználjuk, hogy i² = −{0}. Trigonometrikus alakban a szorzat forgatva nyújtás: az abszolút értékeket szorozzuk, a szögeket összeadjuk. Osztásnál fordítva: az abszolút értékeket osztjuk, a szögeket kivonjuk; algebrai alakban a törtet a nevező konjugáltjával bővítjük.",
"Komplexe Zahlen addiert und subtrahiert man getrennt nach Realteil und Imaginärteil, genau wie Vektoren in der Ebene. Der Betrag der Differenz ist der Abstand der beiden Punkte.": "A komplex számokat valós és képzetes részenként külön adjuk össze és vonjuk ki, ugyanúgy, mint a sík vektorait. A különbség abszolút értéke a két pont távolsága.",
"Bei «Wurzeln» kannst du jede Lösung ziehen: Die Zahl w wird dann als n-te Potenz dieser Lösung neu berechnet.": "A «Gyökök» nézetben bármelyik megoldást húzhatod: a w számot ekkor a program e megoldás n-edik hatványaként számolja újra.",
"Die Punkte rasten beim Ziehen auf runden Werten ein; genaue Werte tippst du links in die Felder.": "Húzás közben a pontok kerek értékekre ugranak; a pontos értékeket bal oldalt, a mezőkbe írhatod be.",
"Die Beträge darf man nicht einfach addieren: {0} (Dreiecksungleichung). Hier: {1}.": "Az abszolút értékeket nem szabad egyszerűen összeadni: {0} (háromszög-egyenlőtlenség). Itt: {1}.",
"<0>Im Bild:</0> Der Zeiger {1} wird an die Spitze von {2} gehängt. Die Summe ist die Diagonale des Parallelogramms mit den Seiten {3} und {4}.": "<0>Az ábrán:</0> a {1} nyilat {2} csúcsához illesztjük. Az összeg a {3} és {4} oldalú paralelogramma átlója.",
"<0>Getrennt rechnen:</0> Realteile und Imaginärteile werden je für sich addiert.": "<0>Külön számolunk:</0> a valós részeket és a képzetes részeket külön-külön adjuk össze.",
"<0>Getrennt rechnen:</0> Realteile und Imaginärteile werden je für sich subtrahiert.": "<0>Külön számolunk:</0> a valós részeket és a képzetes részeket külön-külön vonjuk ki.",
