"<0>Im Bild:</0> Multiplizieren mit {1} dreht den Zeiger {2} um {3} und streckt ihn mit dem Faktor {4} (Drehstreckung). Das Dreieck {5} ist ähnlich zum Dreieck {6}.": "<0>Az ábrán:</0> a {1} számmal való szorzás a {2} nyilat {3} szöggel elforgatja és {4}-szeresére nyújtja (forgatva nyújtás). A {5} háromszög hasonló a {6} háromszöghöz.",
"<0>Polarform:</0> Beträge multiplizieren, Winkel addieren.": "<0>Trigonometrikus alak:</0> az abszolút értékeket szorozzuk, a szögeket összeadjuk.",
"<0>Polarform:</0> Beträge dividieren, Winkel subtrahieren.": "<0>Trigonometrikus alak:</0> az abszolút értékeket osztjuk, a szögeket kivonjuk.",
"<0>Ausmultiplizieren:</0> Jeder Summand wird mit jedem multipliziert, dann setzt man {1} ein.": "<0>Kifejtés:</0> minden tagot minden taggal megszorzunk, majd behelyettesítjük, hogy {1}.",
