"Ziehe {0} und {1}: Beim {2} werden die Beträge multipliziert und die {3}. Die beiden {4} sind ähnlich, denn Multiplizieren mit z₂ dreht um den Winkel von z₂ und streckt mit dessen Betrag. «{5} Drehen und strecken» zeigt die Bewegung.": "Húzd a {0} és a {1} pontot: a {2} az abszolút értékek szorzódnak, a {3}. A két {4} hasonló, mert a z₂-vel való szorzás z₂ szögével forgat és az abszolút értékével nyújt. A «{5} Forgatás és nyújtás» megmutatja a mozgást.",
