"<0>Mit der konjugierten Zahl erweitern:</0> So wird der Nenner reell, denn {1}.": "<0>Bővítés a konjugálttal:</0> így a nevező valós lesz, mert {1}.",
"Durch {0} kann man nicht dividieren. Wähle {1}.": "{0}-val nem lehet osztani. Válassz {1} értéket.",
"Wegen {0} wachsen die Beträge: Die Potenzen laufen auf einer Spirale nach aussen.": "Mivel {0}, az abszolút értékek nőnek: a hatványok spirálban kifelé haladnak.",
"Wegen {0} schrumpfen die Beträge: Die Potenzen laufen auf einer Spirale nach innen.": "Mivel {0}, az abszolút értékek csökkennek: a hatványok spirálban befelé haladnak.",
"Wegen {0} bleiben alle Potenzen auf dem Einheitskreis.": "Mivel {0}, minden hatvány az egységkörön marad.",
"<0>Schritt für Schritt:</0> Jede Multiplikation mit {1} dreht um {2} weiter und streckt mit dem Faktor {3}.": "<0>Lépésről lépésre:</0> minden {1}-vel való szorzás {2} szöggel tovább forgat és {3}-szeresére nyújt.",
"<0>Formel von Moivre:</0> Beim Potenzieren wird der Betrag potenziert und der Winkel vervielfacht.": "<0>Moivre-képlet:</0> hatványozáskor az abszolút értéket hatványozzuk, a szöget megsokszorozzuk.",
