"Ziehe {0} und wähle den Exponenten: Jede {1} dreht um den {2} weiter und streckt mit demselben Faktor. Liegt z auf dem {3}, bleiben alle Potenzen darauf.": "Húzd a {0} pontot, és válaszd meg a kitevőt: minden {1} tovább forgat a {2} és ugyanazzal a tényezővel nyújt. Ha z a {3} van, minden hatvány rajta marad.",
