"Wähle den Grad n und die Zahl w: Die {0} von zⁿ = w liegen auf einem {1} und bilden ein {2}. Ziehe die {3}: Die anderen wandern mit.": "Válaszd meg az n fokot és a w számot: a zⁿ = w egyenlet {0} egy {1} van, és {2} alkot. Húzd a {3}: a többi vele mozog.",
"Für {0} heissen die Lösungen {1}-te Einheitswurzeln. Ihre Summe ist {2}.": "{0} esetén a megoldások az {1}-edik egységgyökök. Összegük {2}.",
"Für {0} ist {1} die einzige Lösung.": "{0} esetén {1} az egyetlen megoldás.",
"Zwei konjugiert komplexe Lösungen: {0}": "Két konjugált komplex megoldás: {0}",
"<0>Im Bild:</0> Die Parabel schneidet die x-Achse nicht. Die beiden Lösungen sind konjugiert zueinander; ihr Realteil ist die Stelle des Scheitels.": "<0>Az ábrán:</0> a parabola nem metszi az x tengelyt. A két megoldás egymás konjugáltja; valós részük a csúcspont első koordinátája.",
"<0>Probe mit dem Satz von Vieta:</0> Summe und Produkt der Lösungen sind reell.": "<0>Ellenőrzés a Viète-formulákkal:</0> a megoldások összege és szorzata valós.",
"<0>Wurzel aus einer negativen Zahl:</0> Wegen {1} ist {2}.": "<0>Negatív szám négyzetgyöke:</0> mivel {1}, ezért {2}.",
"<0>Diskriminante:</0> Sie entscheidet über die Art der Lösungen.": "<0>Diszkrimináns:</0> ez dönti el a megoldások jellegét.",
