"Stelle a, b und c ein: Hat die {0} keine Nullstelle, so hat die Gleichung zwei {1}. Ihr Realteil ist die {2}; in der Gauss-Ebene liegen sie spiegelbildlich zur reellen Achse.": "Állítsd be a, b és c értékét: ha a {0} nincs zérushelye, az egyenletnek két {1} van. Valós részük a {2}; a Gauss-síkon a valós tengelyre tükrösen helyezkednek el.",
"Eine doppelte reelle Lösung: {0}": "Egy kétszeres valós megoldás: {0}",
"<0>Im Bild:</0> Die Parabel berührt die x-Achse im Scheitel.": "<0>Az ábrán:</0> a parabola a csúcspontjában érinti az x tengelyt.",
"Zwei reelle Lösungen: {0} und {1}": "Két valós megoldás: {0} és {1}",
"<0>Im Bild:</0> Die Parabel schneidet die x-Achse zweimal; beide Lösungen liegen auf der reellen Achse der Gauss-Ebene.": "<0>Az ábrán:</0> a parabola kétszer metszi az x tengelyt; mindkét megoldás a Gauss-sík valós tengelyén van.",
"Komplexe Zahlen als Punkte und Zeiger in der Gauss-Ebene: Betrag und Argument, Rechnen als Drehen und Strecken, Potenzen und Wurzeln, quadratische Gleichungen ohne reelle Lösung.": "Komplex számok pontként és nyílként a Gauss-síkon: abszolút érték és argumentum, számolás forgatással és nyújtással, hatványok és gyökök, valós megoldás nélküli másodfokú egyenletek.",
"Winkel im Bogenmass": "Szögek radiánban",
"Winkel werden von der positiven reellen Achse aus im Gegenuhrzeigersinn gemessen. Mit «Winkel im Bogenmass» wechselst du in allen Ansichten zwischen Grad und Bogenmass.": "A szögeket a pozitív valós féltengelytől az óramutató járásával ellentétesen mérjük. A «Szögek radiánban» kapcsolóval minden nézetben válthatsz fok és radián között.",
"Wachstumsmodelle": "Növekedési modellek",
"{0} Wachstumsmodelle": "{0} Növekedési modellek",
"Lineares Wachstum": "Lineáris növekedés",
"Exponentielles Wachstum": "Exponenciális növekedés",
"Beschränktes Wachstum": "Korlátos növekedés",
"Logistisches Wachstum": "Logisztikus növekedés",
"Modelle vergleichen": "Modellek összehasonlítása",
"Lineares, exponentielles, beschränktes und logistisches Wachstum mit Rekursion, Formel und Richtungsfeld; Verdopplungs- und Halbwertszeit, Schranke und Wendepunkt; Modelle vergleichen und an Messdaten anpassen": "Lineáris, exponenciális, korlátos és logisztikus növekedés rekurzióval, képlettel és iránymezővel; duplázódási és felezési idő, korlát és inflexiós pont; modellek összehasonlítása és illesztése mérési adatokhoz",
"Vier Arten, wie ein Bestand wächst oder abnimmt: linear, exponentiell, beschränkt und logistisch. Jedes Modell Schritt für Schritt und als Formel, dazu der Vergleich an echten Messreihen.": "Négyféle módon nőhet vagy csökkenhet egy mennyiség: lineárisan, exponenciálisan, korlátosan és logisztikusan. Minden modell lépésről lépésre és képlettel, valamint összehasonlítás valódi mérési sorokkal.",
"{0} Verändere links Anfangswert und Wachstum und ziehe den Punkt P auf der Kurve. Unter «Modelle vergleichen» passt du die Modelle an Messdaten an.": "{0} Változtasd meg bal oldalt a kezdőértéket és a növekedést, majd húzd a P pontot a görbén. A «Modellek összehasonlítása» nézetben mérési adatokhoz illesztheted a modelleket.",
"Unter «Modelle vergleichen» lädst du über «Beispiel wählen …» eine Messreihe; die mittlere Abweichung sagt, wie gut ein Modell passt.": "A «Modellek összehasonlítása» nézetben a «Példa választása …» menüből tölthetsz be mérési sort; az átlagos eltérés megmutatja, mennyire illik egy modell.",
"Das Richtungsfeld zeigt für jeden Bestand, wie steil die Kurve dort verläuft: Jede Lösungskurve folgt den kleinen Strichen.": "Az iránymező megmutatja, hogy a mennyiség egyes értékeinél milyen meredek a görbe: minden megoldásgörbe a kis vonalkákat követi.",
"Die Zeit läuft in Schritten von einer Zeiteinheit (Stunde, Tag, Jahr …); die grünen Stufen zeigen den Zuwachs pro Schritt.": "Az idő egy időegységnyi lépésekben halad (óra, nap, év …); a zöld lépcsők az egy lépésre jutó növekményt mutatják.",
"Lineares Wachstum: In gleichen Zeitabständen ändert sich der Bestand immer um denselben Betrag. Rekursiv heisst das {0} = {1} + k, als Formel {2} = B₀ + k · t. Beispiele: Sparen ohne Zins, eine Kerze brennt ab, ein Tank wird gefüllt.": "Lineáris növekedés: egyenlő időközönként a mennyiség mindig ugyanannyival változik. Rekurzívan {0} = {1} + k, képlettel {2} = B₀ + k · t. Példák: megtakarítás kamat nélkül, égő gyertya, megtelő tartály.",
"Exponentielles Wachstum: In gleichen Zeitabständen ändert sich der Bestand immer um denselben Prozentsatz, also mit demselben Faktor q. Rekursiv {0} = q · {1}, als Formel {2} = B₀ · qᵗ. Ist q grösser als {3}, wächst der Bestand, sonst zerfällt er. Beispiele: Zinseszins, Bakterien, radioaktiver Zerfall.": "Exponenciális növekedés: egyenlő időközönként a mennyiség mindig ugyanannyi százalékkal, azaz ugyanazzal a q tényezővel változik. Rekurzívan {0} = q · {1}, képlettel {2} = B₀ · qᵗ. Ha q nagyobb, mint {3}, a mennyiség nő, különben csökken. Példák: kamatos kamat, baktériumok, radioaktív bomlás.",
"Beschränktes Wachstum: Der Zuwachs ist proportional zum Abstand von der Schranke S. Rekursiv {0} = {1} + k · (S − {2}). Liegt der Anfangswert über der Schranke, nähert sich der Bestand von oben. Beispiele: Abkühlen und Erwärmen, Medikament bei Dauerinfusion, Lernkurve.": "Korlátos növekedés: a növekmény arányos a korláttól (S) mért távolsággal. Rekurzívan {0} = {1} + k · (S − {2}). Ha a kezdőérték a korlát fölött van, a mennyiség felülről közelít hozzá. Példák: lehűlés és felmelegedés, gyógyszer folyamatos infúziónál, tanulási görbe.",
"Logistisches Wachstum: Die Änderungsrate ist proportional zum Bestand und zum noch freien Platz. Daraus entsteht eine S-förmige Kurve. Beispiele: Ausbreitung einer Krankheit oder eines Gerüchts, Population mit begrenztem Lebensraum, Höhe einer Pflanze.": "Logisztikus növekedés: a változás üteme arányos a mennyiséggel és a még szabad hellyel. Így S alakú görbe jön létre. Példák: egy betegség vagy pletyka terjedése, korlátozott élőhelyű populáció, egy növény magassága.",
"Welches Modell passt, erkennt man an den Daten: Gleiche Differenzen sprechen für lineares, gleiche Quotienten für exponentielles Wachstum. Nähern sich die Werte einer Grenze, ist das Wachstum beschränkt oder, bei S-förmigem Verlauf, logistisch.": "Az adatokból látszik, melyik modell illik: az egyenlő különbségek lineáris, az egyenlő hányadosok exponenciális növekedésre utalnak. Ha az értékek egy határhoz közelítenek, a növekedés korlátos, S alakú lefutásnál pedig logisztikus.",
