"Stelle {0} und Zuwachs pro Zeitschritt ein: Die {1} sind alle gleich hoch, die {2} liegen auf einer {3}. Ziehe den {4}, um den Bestand zu einem beliebigen Zeitpunkt abzulesen.": "Állítsd be: {0} és az időlépésenkénti növekmény. A {1} mind egyforma magasak, a {2} egy {3} vannak. Húzd a {4}, hogy tetszőleges időpontban leolvasd a mennyiséget.",
"Stelle {0} und Prozentsatz ein: Jede der {1} ist um denselben Faktor höher als die vorige, die {2} wird immer steiler. Die {3} ist überall gleich lang. Ziehe den {4}.": "Állítsd be: {0} és a százalék. A {1} minden lépésben ugyanazzal a tényezővel magasabbak, a {2} pedig egyre meredekebb. A {3} mindenütt ugyanakkora. Húzd a {4}.",
"Stelle {0}, {1} und Anteil k ein: Jede der {2} schliesst denselben Anteil der Lücke bis zur Schranke. Die {3} wird immer flacher und kommt der Schranke beliebig nahe. Ziehe den {4}.": "Állítsd be: {0}, {1} és a k hányad. A {2} minden lépésben a korlátig hátralévő rés ugyanakkora hányadát zárják be. A {3} egyre laposabb, és tetszőlegesen megközelíti a korlátot. Húzd a {4}.",
"Stelle {0}, {1} und Wachstumskonstante ein: Die {2} wächst zuerst fast exponentiell, am {3} bei halber Schranke am schnellsten und nähert sich dann der Schranke. Ziehe den {4}.": "Állítsd be: {0}, {1} és a növekedési állandó. A {2} eleinte csaknem exponenciálisan nő, a leggyorsabban a {3}, a korlát felénél, majd a korláthoz közelít. Húzd a {4}.",
"Alle Modelle starten beim selben {0}: {1} und {2}. Verstelle die Regler, bis ein Modell die {3} trifft; die {4} zeigt, welches am besten passt.": "Minden modell ugyanarról az értékről indul ({0}): {1} és {2}. Állítsd a csúszkákat, amíg az egyik modell el nem találja a {3}; az {4} megmutatja, melyik illik a legjobban.",
