"Trage links die {0} und die {1} ein: Jede Zahlung wird mit dem Kalkulationszinssatz zu ihrem {2} abgezinst. Die Summe aller Barwerte ist der {3}; ist er positiv, lohnt sich die Investition.": "Írd be bal oldalt a két adatot ({0}, {1}): minden kifizetést a kalkulatív kamatlábbal a mai értékére számítunk át ({2}). A jelenértékek összege a {3}; ha pozitív, a beruházás megéri.",
"Ziehe den {0} entlang der {1}: Je höher der Zinssatz, desto kleiner der Kapitalwert. Beim {2} ist der Kapitalwert genau null; liegt er über dem Kalkulationszinssatz, lohnt sich die Investition.": "Húzd a pontot ({0}) a görbe mentén ({1}): minél magasabb a kamatláb, annál kisebb a nettó jelenérték. Egy helyen ({2}) a nettó jelenérték pontosan nulla; ha ez a kalkulatív kamatláb fölött van, a beruházás megéri.",
"Die {0} summiert die Zahlungen ohne Zins, die {1} die abgezinsten Zahlungen. Wo eine Linie die Nulllinie kreuzt, ist die Investition zurückgeflossen: nach der {2} und nach der {3}.": "Az egyik vonal ({0}) kamat nélkül összegzi a kifizetéseket, a másik ({1}) a diszkontált kifizetéseket. Ahol egy vonal metszi a nullvonalat, ott térült meg a beruházás: kétféle megtérülési idő van ({2} és {3}).",
"Vergleiche {0} und {1}: Ziehe den {2} und lies ab, welche den grösseren Kapitalwert hat. Am {3} sind beide gleich gut; links und rechts davon ist jeweils eine andere besser.": "Hasonlítsd össze a két lehetőséget ({0} és {1}): húzd a pontot ({2}), és olvasd le, melyiknek nagyobb a nettó jelenértéke. Egy helyen ({3}) a kettő egyformán jó; tőle balra és jobbra más-más a jobb.",
