"Wähle links eine {0} und klicke eine Zeile der {1} an: Die {2} gehört zu einem Feld im {3}. Schraffiert sind die Felder, in denen die verknüpfte Aussage wahr ist.": "Válassz bal oldalt egy műveletet ({0}), és kattints a táblázat egyik sorára ({1}): a {2} az ábra egy mezőjéhez tartozik ({3}). Azok a mezők sraffozottak, ahol az összetett állítás igaz.",
"Tippe links eine {0} ein: Die {1} rechnet sie für alle Belegungen aus, von den {2} bis zur {3}. Steht dort überall «wahr», ist die Aussage eine Tautologie.": "Írj be bal oldalt egy állítást ({0}): a táblázat ({1}) minden kiértékelésre kiszámítja, lépésenként ({2}) egészen a végéig ({3}). Ha ott mindenütt «igaz» áll, az állítás tautológia.",
"Vergleiche die {0} und die {1}: Stimmen ihre Spalten in der {2} überall überein, sind sie gleichwertig; dann sind auch die {3} gleich schraffiert. Unter «Beispiel wählen …» stehen die wichtigsten Gesetze.": "Hasonlítsd össze a két állítást ({0} és {1}): ha oszlopaik a táblázatban ({2}) mindenütt megegyeznek, egyenértékűek; ekkor az ábrák ({3}) is ugyanúgy sraffozottak. A legfontosabb azonosságok a «Válassz példát …» alatt találhatók.",
"Wähle ein Beispiel und klicke eine {0} an: Die {1} ist nur falsch, wenn A wahr und B falsch ist. Die {2} hat dieselben Wahrheitswerte und ist gleichwertig, die {3} nicht. Die {4} ist genau dann wahr, wenn die Implikation falsch ist.": "Válassz példát, és kattints egy oszlopra ({0}): az első állítás ({1}) csak akkor hamis, ha A igaz és B hamis. A harmadik ({2}) igazságértékei ugyanazok, ezért egyenértékű vele, a második ({3}) nem. Az utolsó ({4}) pontosan akkor igaz, amikor az implikáció hamis.",
