"Ziehe die {0} oder klicke in die Fläche, um einen Punkt zu setzen. Das {1} teilt die Ebene in vier Felder: Die {2} zählen positiv, die {3} negativ. Aus ihrer Summe entsteht der {4}.": "Húzd a pontokat ({0}), vagy kattints a grafikon területére egy új pont felvételéhez. A két szaggatott vonal ({1}) négy mezőre osztja a síkot: a {2} pozitívan, a {3} negatívan számítanak. Összegükből adódik a {4}.",
