"Die {0} macht die Summe der Quadrate der {1} so klein wie möglich und geht immer durch den {2}. Ziehe den {3} für eine Vorhersage, oder schalte links eine eigene Gerade ein und vergleiche die {4}.": "A kék vonal ({0}) esetén a legkisebb az eltérések (zöld szakaszok: {1}) négyzetösszege, és mindig átmegy a narancssárga ponton ({2}). Húzd az egyenesen lévő pontot ({3}) az előrejelzéshez, vagy kapcsolj be bal oldalt egy saját egyenest, és hasonlítsd össze az eredményeket ({4}).",
"Gerade der kleinsten Quadrate": "legkisebb négyzetek egyenese",
