"Die {0} erklärt nur einen Teil der Streuung der y-Werte: Der {1} ist das Bestimmtheitsmass r². Unten sind die {2} einzeln aufgetragen. Liegen sie ohne Muster um die {3}, passt eine Gerade; bilden sie einen Bogen, wäre eine Kurve besser.": "A kék egyenes ({0}) az y értékek szóródásának csak egy részét magyarázza: ennek mértéke az r² determinációs együttható ({1}). Lent külön láthatók az egyenestől való eltérések ({2}). Ha minta nélkül helyezkednek el a vízszintes vonal ({3}) körül, az egyenes megfelel; ha ívet alkotnak, egy görbe jobb lenne.",
"roten Punkt Q": "piros Q pont",
