"Ziehe den {0}: Die {1} gehört zu den Daten ohne Q, die {2} zu allen Punkten. Liegt Q in x-Richtung weit aussen, wirkt er wie ein Hebel. Der {3} zeigt, wie stark sich r und die Steigung ändern.": "Húzd a Q pontot ({0}): az első egyenes ({1}) a Q nélküli adatokhoz tartozik, a második ({2}) az összes ponthoz. Ha Q az x irányban messze kint van, emelőként hat. A keret ({3}) megmutatja, mennyire változik r és a meredekség.",
